function(container, apiUrl, tables) {
  const loginForm = container.querySelector('#login-form');
  const usernameInput = container.querySelector('#username');
  const passwordInput = container.querySelector('#password');
  const togglePasswordBtn = container.querySelector('#toggle-password');
  const rememberMeCheckbox = container.querySelector('#remember-me');
  const errorMessage = container.querySelector('#error-message');
  const forgotPasswordLink = container.querySelector('#forgot-password');

  // パスワード表示/非表示切り替え
  togglePasswordBtn.addEventListener('click', () => {
    const isPassword = passwordInput.type === 'password';
    passwordInput.type = isPassword ? 'text' : 'password';
    togglePasswordBtn.textContent = isPassword ? '非表示' : '表示';
  });

  // エラーメッセージ表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.classList.remove('hidden');
  }

  function hideError() {
    errorMessage.classList.add('hidden');
  }

  // ログイン処理
  async function handleLogin(username, password, rememberMe) {
    try {
      // ユーザーテーブル（tables[0]）からユーザー情報を取得
      const users = await window.aivicApi.list(0);
      if (!users) {
        showError('システムエラーが発生しました。管理者にお問い合わせください。');
        return false;
      }

      // ユーザー名とパスワードの照合（実際の実装ではハッシュ化されたパスワードと照合）
      const user = users.find(u => 
        u.ユーザー名 === username && 
        u.有効フラグ === true
      );

      if (!user) {
        showError('ユーザー名またはパスワードが正しくありません。');
        return false;
      }

      // 簡易的なパスワード照合（実際の実装ではハッシュ化されたパスワードと照合）
      // ここではデモ用に平文で比較
      if (user.パスワードハッシュ !== password) {
        showError('ユーザー名またはパスワードが正しくありません。');
        return false;
      }

      // 最終ログイン日時を更新
      await window.aivicApi.update(0, user.ユーザーID, {
        最終ログイン日時: new Date().toISOString()
      });

      // ログイン状態を保持する場合はlocalStorageに保存
      if (rememberMe) {
        localStorage.setItem('worklog_user_id', user.ユーザーID);
        localStorage.setItem('worklog_username', user.ユーザー名);
      }

      // セッションストレージにユーザー情報を保存
      sessionStorage.setItem('current_user', JSON.stringify({
        ユーザーID: user.ユーザーID,
        ユーザー名: user.ユーザー名,
        氏名: user.氏名,
        所属部署: user.所属部署,
        職種: user.職種,
        権限レベル: user.権限レベル
      }));

      return true;
    } catch (error) {
      console.error('Login error:', error);
      showError('ログイン処理中にエラーが発生しました。');
      return false;
    }
  }

  // フォーム送信処理
  loginForm.addEventListener('submit', async (e) => {
    e.preventDefault();
    hideError();

    const username = usernameInput.value.trim();
    const password = passwordInput.value;
    const rememberMe = rememberMeCheckbox.checked;

    if (!username || !password) {
      showError('ユーザー名とパスワードを入力してください。');
      return;
    }

    // ログインボタンを無効化
    const loginBtn = container.querySelector('#btn-login');
    loginBtn.disabled = true;
    loginBtn.textContent = 'ログイン中...';

    try {
      const success = await handleLogin(username, password, rememberMe);

      if (success) {
        // ログイン成功時はメイン画面に遷移
        if (typeof window.onLoginSuccess === 'function') {
          window.onLoginSuccess();
        } else {
          // フォールバック: 工数記録画面に直接遷移
          window.showScreen("scr-1778907133295");
        }
      }
    } finally {
      // ログインボタンを有効化
      loginBtn.disabled = false;
      loginBtn.textContent = 'ログイン';
    }
  });

  // パスワードを忘れた場合のリンク
  forgotPasswordLink.addEventListener('click', (e) => {
    e.preventDefault();
    alert('パスワードリセット機能は管理者にお問い合わせください。');
  });

  // ページ読み込み時に保存されたログイン情報があれば復元
  const savedUserId = localStorage.getItem('worklog_user_id');
  const savedUsername = localStorage.getItem('worklog_username');

  if (savedUserId && savedUsername) {
    usernameInput.value = savedUsername;
    rememberMeCheckbox.checked = true;
    passwordInput.focus();
  } else {
    usernameInput.focus();
  }

  // Enterキーでのフォーム送信を有効化
  usernameInput.addEventListener('keypress', (e) => {
    if (e.key === 'Enter') {
      passwordInput.focus();
    }
  });

  passwordInput.addEventListener('keypress', (e) => {
    if (e.key === 'Enter') {
      loginForm.dispatchEvent(new Event('submit'));
    }
  });
}

function(container, apiUrl, tables) {
  let currentWorkRecord = null;
  let startTime = null;
  let timerInterval = null;
  let pauseStartTime = null;
  let totalPauseTime = 0;

  // 現在時刻表示の更新
  function updateCurrentTime() {
    const now = new Date();
    container.querySelector('#current-time').textContent = now.toLocaleString('ja-JP');
  }

  // 経過時間表示の更新
  function updateElapsedTime() {
    if (!startTime) return;

    const now = new Date();
    let elapsed = now - startTime - totalPauseTime;
    if (pauseStartTime) {
      elapsed -= (now - pauseStartTime);
    }

    const hours = Math.floor(elapsed / (1000 * 60 * 60));
    const minutes = Math.floor((elapsed % (1000 * 60 * 60)) / (1000 * 60));
    const seconds = Math.floor((elapsed % (1000 * 60)) / 1000);

    container.querySelector('#elapsed-time').textContent = 
      `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
  }

  // 作業項目の読み込み
  async function loadWorkItems() {
    const workItems = await window.aivicApi.list(3); // 作業項目マスタ
    const select = container.querySelector('#work-item');
    select.innerHTML = '<option value="">作業項目を選択してください</option>';

    if (workItems) {
      workItems
        .filter(item => item.有効フラグ)
        .sort((a, b) => (a.表示順序 || 0) - (b.表示順序 || 0))
        .forEach(item => {
          const option = document.createElement('option');
          option.value = item.作業項目ID;
          option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
          select.appendChild(option);
        });
    }
  }

  // 本日の作業履歴を表示
  async function renderTodayHistory() {
    const records = await window.aivicApi.list(1); // 作業記録
    const tbody = container.querySelector('#today-history');

    if (!records) {
      tbody.innerHTML = '<tr><td colspan="4" style="text-align: center; padding: 20px; color: var(--text-muted);">データの読み込みに失敗しました</td></tr>';
      return;
    }

    const today = new Date().toDateString();
    const todayRecords = records.filter(record => {
      const recordDate = new Date(record.作業日).toDateString();
      return recordDate === today;
    });

    if (todayRecords.length === 0) {
      tbody.innerHTML = '<tr><td colspan="4" style="text-align: center; padding: 20px; color: var(--text-muted);">本日の作業履歴はありません</td></tr>';
      return;
    }

    tbody.innerHTML = todayRecords.map(record => {
      const startTime = new Date(record.作業開始時刻).toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });
      const workTime = record.作業時間 ? `${Math.floor(record.作業時間 / 60)}:${(record.作業時間 % 60).toString().padStart(2, '0')}` : '-';
      const statusColor = record.進捗状況 === '完了' ? '#22c55e' : record.進捗状況 === '作業中' ? '#3b82f6' : '#f59e0b';

      return `
        <tr>
          <td style="padding: 6px 8px;">${startTime}</td>
          <td style="padding: 6px 8px;">${record.作業種別 || '-'}</td>
          <td style="padding: 6px 8px;">${workTime}</td>
          <td style="padding: 6px 8px;"><span style="color: ${statusColor}; font-size: 11px;">${record.進捗状況}</span></td>
        </tr>
      `;
    }).join('');
  }

  // 作業開始
  container.querySelector('#btn-start').addEventListener('click', async () => {
    const workItemId = container.querySelector('#work-item').value;
    if (!workItemId) {
      alert('作業項目を選択してください');
      return;
    }

    const workItems = await window.aivicApi.list(3);
    const selectedItem = workItems?.find(item => item.作業項目ID === workItemId);

    const newRecord = {
      作業員ID: 'current-user-id', // 実際の実装では認証されたユーザーIDを使用
      作業日: new Date().toISOString(),
      作業開始時刻: new Date().toISOString(),
      プロジェクト名: selectedItem?.作業項目名|| '',
      作業場所: '現場A', // 実際の実装では選択可能にする
      作業種別: selectedItem?.作業項目名|| '',
      作業内容: '',
      進捗状況: '作業中',
      承認状態: '未承認',
      作成者ID: 'current-user-id'
    };

    const saved = await window.aivicApi.save(1, newRecord);
    if (saved) {
      currentWorkRecord = saved;
      startTime = new Date();
      totalPauseTime = 0;
      pauseStartTime = null;

      // ボタン状態更新
      container.querySelector('#btn-start').disabled = true;
      container.querySelector('#btn-end').disabled = false;
      container.querySelector('#btn-pause').disabled = false;
      container.querySelector('#work-item').disabled = true;

      // タイマー開始
      timerInterval = setInterval(updateElapsedTime, 1000);

      renderTodayHistory();
    }
  });

  // 作業終了
  container.querySelector('#btn-end').addEventListener('click', async () => {
    if (!currentWorkRecord) return;

    const endTime = new Date();
    let workTime = Math.floor((endTime - startTime - totalPauseTime) / (1000 * 60)); // 分単位
    if (pauseStartTime) {
      workTime -= Math.floor((endTime - pauseStartTime) / (1000 * 60));
    }

    const memo = container.querySelector('#work-memo').value;

    const updated = await window.aivicApi.update(1, currentWorkRecord.作業記録ID, {
      作業終了時刻: endTime.toISOString(),
      作業時間: workTime,
      作業内容: memo,
      進捗状況: '完了'
    });

    if (updated) {
      // 状態リセット
      currentWorkRecord = null;
      startTime = null;
      totalPauseTime = 0;
      pauseStartTime = null;
      clearInterval(timerInterval);

      // UI リセット
      container.querySelector('#btn-start').disabled = false;
      container.querySelector('#btn-end').disabled = true;
      container.querySelector('#btn-pause').disabled = true;
      container.querySelector('#work-item').disabled = false;
      container.querySelector('#work-item').value = '';
      container.querySelector('#work-memo').value = '';
      container.querySelector('#elapsed-time').textContent = '00:00:00';

      renderTodayHistory();
    }
  });

  // 中断
  container.querySelector('#btn-pause').addEventListener('click', () => {
    container.querySelector('#pause-reason-area').classList.remove('hidden');
  });

  // 中断確定
  container.querySelector('#btn-confirm-pause').addEventListener('click', async () => {
    const reason = container.querySelector('#pause-reason').value;
    const detail = container.querySelector('#pause-detail').value;

    if (!reason) {
      alert('中断理由を選択してください');
      return;
    }

    if (currentWorkRecord) {
      pauseStartTime = new Date();

      const pauseRecord = {
        作業記録ID: currentWorkRecord.作業記録ID,
        中断開始日時: pauseStartTime.toISOString(),
        中断理由区分: reason,
        中断理由詳細: detail,
        対応状況: '対応中',
        記録者ID: 'current-user-id'
      };

      await window.aivicApi.save(2, pauseRecord); // 中断記録
    }

    container.querySelector('#pause-reason-area').classList.add('hidden');
    container.querySelector('#pause-reason').value = '';
    container.querySelector('#pause-detail').value = '';
  });

  // 中断キャンセル
  container.querySelector('#btn-cancel-pause').addEventListener('click', () => {
    container.querySelector('#pause-reason-area').classList.add('hidden');
    container.querySelector('#pause-reason').value = '';
    container.querySelector('#pause-detail').value = '';
  });

  // 保存
  container.querySelector('#btn-save').addEventListener('click', async () => {
    if (!currentWorkRecord) return;

    const memo = container.querySelector('#work-memo').value;

    const updated = await window.aivicApi.update(1, currentWorkRecord.作業記録ID, {
      作業内容: memo
    });

    if (updated) {
      alert('作業メモを保存しました');
    }
  });

  // キャンセル
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    if (currentWorkRecord && confirm('作業中ですが、本当にキャンセルしますか？')) {
      // 作業記録を削除
      window.aivicApi.delete(1, currentWorkRecord.作業記録ID);

      // 状態リセット
      currentWorkRecord = null;
      startTime = null;
      totalPauseTime = 0;
      pauseStartTime = null;
      clearInterval(timerInterval);

      // UI リセット
      container.querySelector('#btn-start').disabled = false;
      container.querySelector('#btn-end').disabled = true;
      container.querySelector('#btn-pause').disabled = true;
      container.querySelector('#work-item').disabled = false;
      container.querySelector('#work-item').value = '';
      container.querySelector('#work-memo').value = '';
      container.querySelector('#elapsed-time').textContent = '00:00:00';

      renderTodayHistory();
    }
  });

  // 初期化
  updateCurrentTime();
  setInterval(updateCurrentTime, 1000);
  loadWorkItems();
  renderTodayHistory();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#work-history-tbody");

  // 1. テーブル再描画関数を定義
  async function renderRows(workRecords) {
    // 中断記録を取得して中断回数を計算
    const interruptRecords = await window.aivicApi.list(2) || [];

    tbody.innerHTML = workRecords.map(record => {
      const startTime = record.作業開始時刻 ? new Date(record.作業開始時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '';
      const endTime = record.作業終了時刻 ? new Date(record.作業終了時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '';
      const workDate = record.作業日 ? new Date(record.作業日).toLocaleDateString('ja-JP') : '';
      const workTime = record.作業時間 ? `${Math.floor(record.作業時間 / 60)}h${record.作業時間 % 60}m` : '';

      // この作業記録の中断回数を計算
      const interruptCount = interruptRecords.filter(interrupt => interrupt.作業記録ID === record.作業記録ID).length;

      // 進捗状況のスタイル
      let statusStyle = '';
      if (record.進捗状況 === '完了') {
        statusStyle = 'background: rgba(34, 197, 94, 0.1); color: #22c55e; padding: 2px 6px; border-radius: 4px; font-size: 11px;';
      } else if (record.進捗状況 === '作業中') {
        statusStyle = 'background: rgba(59, 130, 246, 0.1); color: #3b82f6; padding: 2px 6px; border-radius: 4px; font-size: 11px;';
      } else if (record.進捗状況 === '中断') {
        statusStyle = 'background: rgba(239, 68, 68, 0.1); color: #ef4444; padding: 2px 6px; border-radius: 4px; font-size: 11px;';
      }

      return `
        <tr data-id="${record.作業記録ID || ''}" style="cursor: pointer;">
          <td>${workDate}</td>
          <td>${record.作業種別 || ''}</td>
          <td>${startTime}</td>
          <td>${endTime}</td>
          <td>${workTime}</td>
          <td style="text-align: center;">${interruptCount}</td>
          <td><span style="${statusStyle}">${record.進捗状況 || ''}</span></td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${record.作業記録ID || ''}">詳細確認</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 2. 初期データを即座に描画
  renderRows(tables[1]?.records || []);

  // 3. 検索ボタンのイベントリスナー
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const dateFrom = container.querySelector("#filter-date-from").value;
    const dateTo = container.querySelector("#filter-date-to").value;
    const status = container.querySelector("#filter-status").value;

    const allRecords = await window.aivicApi.list(1);
    if (!allRecords) return;

    const filteredRecords = allRecords.filter(record => {
      let match = true;

      if (dateFrom && record.作業日) {
        const recordDate = new Date(record.作業日).toISOString().split('T')[0];
        if (recordDate < dateFrom) match = false;
      }

      if (dateTo && record.作業日) {
        const recordDate = new Date(record.作業日).toISOString().split('T')[0];
        if (recordDate > dateTo) match = false;
      }

      if (status && record.進捗状況 !== status) match = false;

      return match;
    });

    renderRows(filteredRecords);
  });

  // 4. リセットボタン
  container.querySelector("#btn-reset").addEventListener("click", async () => {
    container.querySelector("#filter-date-from").value = '';
    container.querySelector("#filter-date-to").value = '';
    container.querySelector("#filter-status").value = '';

    const allRecords = await window.aivicApi.list(1);
    if (allRecords) renderRows(allRecords);
  });

  // 5. CSVエクスポートボタン
  container.querySelector("#btn-export").addEventListener("click", async () => {
    const allRecords = await window.aivicApi.list(1);
    if (!allRecords) return;

    const interruptRecords = await window.aivicApi.list(2) || [];

    const csvData = [
      ['作業日時', '作業項目名', '開始時刻', '終了時刻', '作業時間(分)', '中断回数', '進捗状況', '作業場所', '作業内容']
    ];

    allRecords.forEach(record => {
      const interruptCount = interruptRecords.filter(interrupt => interrupt.作業記録ID === record.作業記録ID).length;
      csvData.push([
        record.作業日 ? new Date(record.作業日).toLocaleDateString('ja-JP') : '',
        record.作業種別 || '',
        record.作業開始時刻 ? new Date(record.作業開始時刻).toLocaleTimeString('ja-JP') : '',
        record.作業終了時刻 ? new Date(record.作業終了時刻).toLocaleTimeString('ja-JP') : '',
        record.作業時間 || '',
        interruptCount,
        record.進捗状況 || '',
        record.作業場所 || '',
        record.作業内容 || ''
      ]);
    });

    const csvContent = '\uFEFF' + csvData.map(row => 
      row.map(field => `"${String(field).replace(/"/g, '""')}"`).join(',')
    ).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `作業履歴一覧_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 6. 画面遷移のイベントリスナー
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      window.showScreen("scr-1778907367889");
      return;
    }
  });

  container.querySelector("#btn-extract").addEventListener("click", () => {
    window.showScreen("scr-1778907353387");
  });

  container.querySelector("#btn-back").addEventListener("click", () => {
    window.showScreen("scr-1778907133295");
  });

  // 初期データの再読み込み
  window.aivicApi.list(1).then(records => {
    if (records) renderRows(records);
  });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#anomaly-log-tbody");
  const detailArea = container.querySelector("#detail-area");
  let selectedLogId = null;
  let currentLogs = [];

  // 1. 再描画関数の定義
  function renderRows(rows) {
    currentLogs = rows;
    tbody.innerHTML = rows.map(r => {
      const detectionDate = r.検出日時 ? new Date(r.検出日時).toLocaleString('ja-JP', {
        year: 'numeric', month: '2-digit', day: '2-digit',
        hour: '2-digit', minute: '2-digit'
      }) : '';

      const severityColor = r.重要度 === '高' ? '#ff4444' : r.重要度 === '中' ? '#ff8800' : '#888888';
      const statusColor = r.確認状況 === '未確認' ? '#ff4444' : r.確認状況 === '確認済み' ? '#ff8800' : '#22aa22';

      return `<tr data-id="${r.異常値検出ログID || r.id}" style="cursor: pointer;">
        <td>${detectionDate}</td>
        <td>${r.作業員名 || ''}</td>
        <td>${r.異常値種別 || ''}</td>
        <td>${r.検出項目 || ''}</td>
        <td>${r.検出値 || ''}</td>
        <td>${r.閾値 || ''}</td>
        <td><span style="color: ${severityColor}; font-weight: 500;">${r.重要度 || ''}</span></td>
        <td><span style="color: ${statusColor}; font-weight: 500;">${r.確認状況 || ''}</span></td>
        <td>${r.確認者名 || ''}</td>
        <td><button class="action-btn secondary detail-btn" data-id="${r.異常値検出ログID || r.id}">詳細</button></td>
      </tr>`;
    }).join("");
  }

  // 2. 初期データ読み込み
  window.aivicApi.list(5).then(rows => {
    if (rows) {
      renderRows(rows);
    }
  });

  // 3. 検索機能
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const dateStart = container.querySelector("#filter-date-start").value;
    const dateEnd = container.querySelector("#filter-date-end").value;
    const anomalyType = container.querySelector("#filter-anomaly-type").value;
    const severity = container.querySelector("#filter-severity").value;
    const workerName = container.querySelector("#filter-worker-name").value;
    const status = container.querySelector("#filter-status").value;

    const rows = await window.aivicApi.list(5);
    if (!rows) return;

    const filtered = rows.filter(r => {
      if (dateStart && r.検出日時 && new Date(r.検出日時) < new Date(dateStart)) return false;
      if (dateEnd && r.検出日時 && new Date(r.検出日時) > new Date(dateEnd)) return false;
      if (anomalyType && r.異常値種別 !== anomalyType) return false;
      if (severity && r.重要度 !== severity) return false;
      if (workerName && (!r.作業員名 || !r.作業員名.includes(workerName))) return false;
      if (status && r.確認状況 !== status) return false;
      return true;
    });

    renderRows(filtered);
  });

  // 4. フィルタークリア
  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#filter-date-start").value = '';
    container.querySelector("#filter-date-end").value = '';
    container.querySelector("#filter-anomaly-type").value = '';
    container.querySelector("#filter-severity").value = '';
    container.querySelector("#filter-worker-name").value = '';
    container.querySelector("#filter-status").value = '';

    window.aivicApi.list(5).then(rows => {
      if (rows) renderRows(rows);
    });
  });

  // 5. CSVエクスポート
  container.querySelector("#btn-export").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(5);
    if (!rows) return;

    const headers = ['検出日時', '作業員名', '異常値種別', '検出項目', '検出値', '閾値', '重要度', '確認状況', '確認者名', '対応メモ'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...rows.map(r => [
        r.検出日時 || '',
        r.作業員名 || '',
        r.異常値種別 || '',
        r.検出項目 || '',
        r.検出値 || '',
        r.閾値 || '',
        r.重要度 || '',
        r.確認状況 || '',
        r.確認者名 || '',
        (r.対応メモ || '').replace(/"/g, '""')
      ].map(field => `"${field}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `異常値検出ログ_${new Date().toISOString().slice(0,10)}.csv`;
    link.click();
  });

  // 6. 詳細表示・対応状況更新
  container.addEventListener("click", async (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    const row = e.target.closest("tr[data-id]");

    if (detailBtn || (row && !e.target.closest("button"))) {
      const logId = detailBtn ? detailBtn.dataset.id : row.dataset.id;
      selectedLogId = logId;

      const logData = currentLogs.find(r => (r.異常値検出ログID || r.id) === logId);
      if (!logData) return;

      // 詳細エリア表示
      detailArea.classList.remove("hidden");
      container.querySelector("#detail-target").textContent = 
        `${logData.検出対象テーブル || ''} - ${logData.作業員名 || ''}`;
      container.querySelector("#detail-anomaly").textContent = 
        `${logData.異常値種別 || ''}: ${logData.検出項目 || ''} = ${logData.検出値 || ''} (閾値: ${logData.閾値 || ''})`;
      container.querySelector("#detail-status").value = logData.確認状況 || '未確認';
      container.querySelector("#detail-memo").value = logData.対応メモ || '';

      // スクロール
      detailArea.scrollIntoView({ behavior: 'smooth' });
    }
  });

  // 7. 対応状況更新
  container.querySelector("#btn-update-status").addEventListener("click", async () => {
    if (!selectedLogId) return;

    const status = container.querySelector("#detail-status").value;
    const memo = container.querySelector("#detail-memo").value;

    const updated = await window.aivicApi.update(5, selectedLogId, {
      確認状況: status,
      対応メモ: memo,
      確認日時: new Date().toISOString(),
      確認者ID: 'current-user-id' // 実際の実装では現在のユーザーIDを使用
    });

    if (updated) {
      // 一覧を再読み込み
      const rows = await window.aivicApi.list(5);
      if (rows) renderRows(rows);

      alert('対応状況を更新しました');
    }
  });

  // 8. 元記録確認
  container.querySelector("#btn-view-record").addEventListener("click", () => {
    if (!selectedLogId) return;

    const logData = currentLogs.find(r => (r.異常値検出ログID || r.id) === selectedLogId);
    if (logData && logData.検出対象テーブル === '作業記録') {
      window.showScreen("scr-1778907145716"); // 作業履歴一覧画面
    }
  });
}

function(container, apiUrl, tables) {
  // 現在時刻の更新
  function updateCurrentTime() {
    const now = new Date();
    const timeStr = now.toLocaleString('ja-JP', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit'
    });
    container.querySelector('#current-time').textContent = timeStr;
  }

  // 初期時刻表示と1分ごとの更新
  updateCurrentTime();
  setInterval(updateCurrentTime, 60000);

  // 作業員名表示（仮のユーザー情報）
  const currentUser = tables[0]?.records?.[0] || { 氏名: '作業員' };
  container.querySelector('#worker-name').textContent = currentUser.氏名 || '作業員';

  // 作業項目マスタの読み込み
  function loadWorkItems() {
    const workItemSelect = container.querySelector('#work-item-select');
    const workItems = tables[3]?.records || [];

    workItemSelect.innerHTML = '<option value="">選択してください</option>';
    workItems
      .filter(item => item.有効フラグ)
      .sort((a, b) => (a.表示順序 || 0) - (b.表示順序 || 0))
      .forEach(item => {
        const option = document.createElement('option');
        option.value = item.作業項目ID;
        option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
        workItemSelect.appendChild(option);
      });
  }

  // 進行中作業の表示
  function renderActiveWorks(works) {
    const container_elem = container.querySelector('#active-works');
    if (!works || works.length === 0) {
      container_elem.innerHTML = '<div style="color: var(--text-muted); font-size: 12px; text-align: center; padding: 16px;">進行中の作業はありません</div>';
      return;
    }

    container_elem.innerHTML = works.map(work => `
      <div style="border: 1px solid var(--border); border-radius: 6px; padding: 8px; margin-bottom: 6px; background: var(--bg-main);">
        <div style="font-size: 12px; font-weight: 500; color: var(--text); margin-bottom: 4px;">${work.作業内容 || '-'}</div>
        <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">場所: ${work.作業場所 || '-'}</div>
        <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 6px;">開始: ${work.作業開始時刻 ? new Date(work.作業開始時刻).toLocaleString('ja-JP') : '-'}</div>
        <div style="display: flex; gap: 6px;">
          <button class="action-btn secondary suspend-btn" data-id="${work.作業記録ID}" style="font-size: 11px; padding: 4px 8px;">中断</button>
          <button class="action-btn complete-btn" data-id="${work.作業記録ID}" style="font-size: 11px; padding: 4px 8px;">完了</button>
        </div>
      </div>
    `).join('');
  }

  // 中断中作業の表示
  function renderSuspendedWorks(works) {
    const tbody = container.querySelector('#suspended-works');
    if (!works || works.length === 0) {
      tbody.innerHTML = '<tr><td colspan="5" style="text-align: center; color: var(--text-muted); font-size: 12px; padding: 16px;">中断中の作業はありません</td></tr>';
      return;
    }

    tbody.innerHTML = works.map(work => `
      <tr data-id="${work.作業記録ID}">
        <td style="padding: 6px 10px; font-size: 12px;">${work.作業内容 || '-'}</td>
        <td style="padding: 6px 10px; font-size: 12px;">${work.作業場所 || '-'}</td>
        <td style="padding: 6px 10px; font-size: 12px;">${work.作業開始時刻 ? new Date(work.作業開始時刻).toLocaleString('ja-JP') : '-'}</td>
        <td style="padding: 6px 10px; font-size: 12px;">${work.備考 || '-'}</td>
        <td style="padding: 6px 10px;">
          <button class="action-btn secondary resume-btn" data-id="${work.作業記録ID}" style="font-size: 11px; padding: 4px 8px;">再開</button>
        </td>
      </tr>
    `).join('');
  }

  // データ読み込みと表示
  async function loadWorkData() {
    try {
      const workRecords = await window.aivicApi.list(1) || [];
      const activeWorks = workRecords.filter(work => work.進捗状況 === '作業中');
      const suspendedWorks = workRecords.filter(work => work.進捗状況 === '中断');

      renderActiveWorks(activeWorks);
      renderSuspendedWorks(suspendedWorks);
    } catch (error) {
      console.error('作業データの読み込みに失敗しました:', error);
    }
  }

  // 初期データ読み込み
  loadWorkItems();
  loadWorkData();

  // 作業開始ボタン
  container.querySelector('#btn-start-work').addEventListener('click', async () => {
    const workItemId = container.querySelector('#work-item-select').value;
    const location = container.querySelector('#work-location').value.trim();
    const memo = container.querySelector('#work-memo').value.trim();

    if (!workItemId) {
      alert('作業項目を選択してください');
      return;
    }
    if (!location) {
      alert('作業場所を入力してください');
      return;
    }

    const workItems = tables[3]?.records || [];
    const selectedItem = workItems.find(item => item.作業項目ID === workItemId);

    const workData = {
      作業員ID: currentUser.ユーザーID || 'user-001',
      作業日: new Date().toISOString(),
      作業開始時刻: new Date().toISOString(),
      プロジェクト名: selectedItem?.作業項目名|| '未設定',
      作業場所: location,
      作業種別: selectedItem?.カテゴリ || '一般作業',
      作業内容: selectedItem?.作業項目名|| '',
      進捗状況: '作業中',
      備考: memo,
      承認状態: '未承認',
      作成者ID: currentUser.ユーザーID || 'user-001'
    };

    const saved = await window.aivicApi.save(1, workData);
    if (saved) {
      // フォームクリア
      container.querySelector('#work-item-select').value = '';
      container.querySelector('#work-location').value = '';
      container.querySelector('#work-memo').value = '';

      // データ再読み込み
      loadWorkData();
      alert('作業を開始しました');
    }
  });

  // 工数入力画面への遷移
  container.querySelector('#btn-work-input').addEventListener('click', () => {
    window.showScreen("scr-1778907296658");
  });

  // 設定・ログアウトボタン（仮実装）
  container.querySelector('#btn-settings').addEventListener('click', () => {
    alert('設定画面は未実装です');
  });

  container.querySelector('#btn-logout').addEventListener('click', () => {
    if (confirm('ログアウトしますか？')) {
      // ログアウト処理（仮）
      alert('ログアウトしました');
    }
  });

  // 作業操作のイベントデリゲーション
  container.addEventListener('click', async (e) => {
    // 中断ボタン
    const suspendBtn = e.target.closest('.suspend-btn');
    if (suspendBtn) {
      const workId = suspendBtn.dataset.id;
      const reason = prompt('中断理由を入力してください:');
      if (reason) {
        // 作業記録を中断状態に更新
        await window.aivicApi.update(1, workId, { 進捗状況: '中断', 備考: reason });

        // 中断記録を作成
        const suspendData = {
          作業記録ID: workId,
          中断開始日時: new Date().toISOString(),
          中断理由区分: '作業中断',
          中断理由詳細: reason,
          対応状況: '対応中',
          記録者ID: currentUser.ユーザーID || 'user-001'
        };
        await window.aivicApi.save(2, suspendData);

        loadWorkData();
      }
      return;
    }

    // 完了ボタン
    const completeBtn = e.target.closest('.complete-btn');
    if (completeBtn) {
      const workId = completeBtn.dataset.id;
      if (confirm('作業を完了しますか？')) {
        await window.aivicApi.update(1, workId, {
          進捗状況: '完了',
          作業終了時刻: new Date().toISOString()
        });
        loadWorkData();
      }
      return;
    }

    // 再開ボタン
    const resumeBtn = e.target.closest('.resume-btn');
    if (resumeBtn) {
      const workId = resumeBtn.dataset.id;
      if (confirm('作業を再開しますか？')) {
        await window.aivicApi.update(1, workId, { 進捗状況: '作業中' });

        // 中断記録の終了時刻を更新
        const suspendRecords = await window.aivicApi.list(2) || [];
        const activeSuspend = suspendRecords.find(s => s.作業記録ID === workId && !s.中断終了日時);
        if (activeSuspend) {
          await window.aivicApi.update(2, activeSuspend.中断記録ID, {
            中断終了日時: new Date().toISOString(),
            対応状況: '解決済み'
          });
        }

        loadWorkData();
      }
      return;
    }
  });

  // フォーカス時のスタイル適用
  const inputs = container.querySelectorAll('input, select, textarea');
  inputs.forEach(input => {
    input.addEventListener('focus', () => {
      input.style.outline = 'none';
      input.style.borderColor = 'var(--primary)';
      input.style.boxShadow = '0 0 0 2px rgba(139, 69, 19, 0.15)';
    });
    input.addEventListener('blur', () => {
      input.style.borderColor = 'var(--border)';
      input.style.boxShadow = 'none';
    });
  });
}

function(container, apiUrl, tables) {
  let currentWorkRecord = null;
  let breakRecords = [];

  // 現在進行中の作業記録を取得
  async function loadCurrentWorkRecord() {
    const workRecords = await window.aivicApi.list(1); // 作業記録テーブル
    if (!workRecords) return;

    // 終了時刻がnullの作業中レコードを取得
    currentWorkRecord = workRecords.find(r => !r.作業終了時刻);

    if (currentWorkRecord) {
      // 中断記録も取得
      const allBreakRecords = await window.aivicApi.list(2); // 中断記録テーブル
      if (allBreakRecords) {
        breakRecords = allBreakRecords.filter(b => b.作業記録ID === currentWorkRecord.作業記録ID);
      }

      displayWorkRecord();
    }
  }

  // 作業記録情報を画面に表示
  function displayWorkRecord() {
    if (!currentWorkRecord) return;

    container.querySelector('#work-item-name').textContent = currentWorkRecord.作業種別 || '-';
    container.querySelector('#work-location').textContent = currentWorkRecord.作業場所 || '-';

    const startTime = new Date(currentWorkRecord.作業開始時刻);
    container.querySelector('#start-time').textContent = startTime.toLocaleString('ja-JP');

    // 現在時刻を終了時刻の初期値に設定
    const now = new Date();
    const endTimeInput = container.querySelector('#end-time');
    endTimeInput.value = now.toISOString().slice(0, 16);

    updateTimeCalculation();
  }

  // 時間計算を更新
  function updateTimeCalculation() {
    if (!currentWorkRecord) return;

    const startTime = new Date(currentWorkRecord.作業開始時刻);
    const endTimeInput = container.querySelector('#end-time');

    if (endTimeInput.value) {
      const endTime = new Date(endTimeInput.value);
      const totalMinutes = Math.floor((endTime - startTime) / (1000 * 60));

      // 中断時間の合計を計算
      let breakMinutes = 0;
      breakRecords.forEach(b => {
        if (b.中断時間) {
          breakMinutes += b.中断時間;
        }
      });

      const actualMinutes = totalMinutes - breakMinutes;

      container.querySelector('#total-work-time').textContent = `${Math.floor(totalMinutes / 60)}時間${totalMinutes % 60}分`;
      container.querySelector('#break-time').textContent = `${Math.floor(breakMinutes / 60)}時間${breakMinutes % 60}分`;
      container.querySelector('#actual-work-time').textContent = `${Math.floor(actualMinutes / 60)}時間${actualMinutes % 60}分`;
    }
  }

  // 異常報告チェックボックスの制御
  container.querySelector('#has-issue').addEventListener('change', (e) => {
    const issueSection = container.querySelector('#issue-section');
    if (e.target.checked) {
      issueSection.style.display = 'block';
    } else {
      issueSection.style.display = 'none';
      container.querySelector('#issue-content').value = '';
    }
  });

  // 終了時刻変更時の時間再計算
  container.querySelector('#end-time').addEventListener('change', updateTimeCalculation);

  // 記録確定ボタン
  container.querySelector('#btn-confirm').addEventListener('click', async () => {
    if (!currentWorkRecord) {
      alert('作業記録が見つかりません');
      return;
    }

    const endTimeInput = container.querySelector('#end-time');
    if (!endTimeInput.value) {
      alert('終了時刻を入力してください');
      return;
    }

    const endTime = new Date(endTimeInput.value);
    const startTime = new Date(currentWorkRecord.作業開始時刻);
    const workMinutes = Math.floor((endTime - startTime) / (1000 * 60));

    if (workMinutes <= 0) {
      alert('終了時刻は開始時刻より後に設定してください');
      return;
    }

    const workMemo = container.querySelector('#work-memo').value;
    const completionStatus = container.querySelector('#completion-status').value;
    const hasIssue = container.querySelector('#has-issue').checked;
    const issueContent = container.querySelector('#issue-content').value;

    if (hasIssue && !issueContent.trim()) {
      alert('異常・問題の内容を入力してください');
      return;
    }

    // 作業記録を更新
    const updateData = {
      作業終了時刻: endTime.toISOString(),
      作業時間: workMinutes,
      作業内容: workMemo || currentWorkRecord.作業内容,
      進捗状況: completionStatus,
      備考: hasIssue ? `【異常報告】${issueContent}` : (currentWorkRecord.備考 || ''),
      更新日時: new Date().toISOString()
    };

    const updated = await window.aivicApi.update(1, currentWorkRecord.作業記録ID, updateData);

    if (updated) {
      // 異常値検出ログの作成（長時間作業の場合）
      if (workMinutes > 480) { // 8時間超過
        await window.aivicApi.save(4, {
          異常値検出ログID: crypto.randomUUID(),
          検出対象テーブル: '作業記録',
          検出対象レコードID: currentWorkRecord.作業記録ID,
          ユーザーID: currentWorkRecord.作業員ID,
          異常値種別: '長時間作業',
          検出項目: '作業時間',
          検出値: `${workMinutes}分`,
          閾値: '480分',
          重要度: '中',
          確認状況: '未確認',
          通知送信フラグ: false,
          検出日時: new Date().toISOString(),
          作成日時: new Date().toISOString(),
          更新日時: new Date().toISOString()
        });
      }

      alert('工数記録を完了しました');
      // メイン画面に戻る
      window.showScreen('main');
    }
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    if (confirm('記録を完了せずに戻りますか？')) {
      window.showScreen('main');
    }
  });

  // 記録確認ボタン
  container.querySelector('#btn-view-record').addEventListener('click', () => {
    window.showScreen("scr-1778907226171");
  });

  // 初期データ読み込み
  loadCurrentWorkRecord();
}

function(container, apiUrl, tables) {
  // ローカルストレージキー
  const LOCAL_STORAGE_KEY = 'work_records_local';
  const SETTINGS_KEY = 'autosave_settings';

  // 設定の初期化
  let settings = {
    interval: 60,
    localSave: 'enabled'
  };

  try {
    const savedSettings = localStorage.getItem(SETTINGS_KEY);
    if (savedSettings) {
      settings = { ...settings, ...JSON.parse(savedSettings) };
    }
  } catch (e) {
    console.error('設定読み込みエラー:', e);
  }

  // UI要素の取得
  const statusIndicator = container.querySelector('#status-indicator');
  const statusText = container.querySelector('#status-text');
  const networkIndicator = container.querySelector('#network-indicator');
  const networkText = container.querySelector('#network-text');
  const pendingCount = container.querySelector('#pending-count');
  const lastSaveTime = container.querySelector('#last-save-time');
  const localDataTbody = container.querySelector('#local-data-tbody');
  const errorNotifications = container.querySelector('#error-notifications');
  const errorList = container.querySelector('#error-list');

  // ローカルデータ再描画関数
  function renderLocalData() {
    try {
      const localData = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || '{}');
      const rows = Object.keys(localData).map(key => {
        const data = localData[key];
        const count = Array.isArray(data) ? data.length : Object.keys(data).length;
        const lastUpdate = data.lastUpdate || '未更新';
        const status = data.synced ? '同期済み' : '同期待ち';

        return `
          <tr data-key="${key}">
            <td>${key}</td>
            <td>${count}</td>
            <td style="font-size: 11px;">${lastUpdate}</td>
            <td>
              <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; background: ${data.synced ? '#22c55e' : '#f59e0b'}; color: white;">
                ${status}
              </span>
            </td>
            <td>
              <button class="action-btn secondary sync-btn" data-key="${key}" style="font-size: 11px; padding: 4px 8px;">同期</button>
            </td>
          </tr>
        `;
      });

      localDataTbody.innerHTML = rows.join('');

      // 同期待ち件数の更新
      const pendingItems = Object.values(localData).filter(data => !data.synced).length;
      pendingCount.textContent = pendingItems;

    } catch (e) {
      console.error('ローカルデータ描画エラー:', e);
      localDataTbody.innerHTML = '<tr><td colspan="5">データ読み込みエラー</td></tr>';
    }
  }

  // ネットワーク状態チェック
  function checkNetworkStatus() {
    const isOnline = navigator.onLine;
    networkIndicator.style.background = isOnline ? '#22c55e' : '#ef4444';
    networkText.textContent = isOnline ? 'オンライン' : 'オフライン';

    if (!isOnline) {
      statusIndicator.style.background = '#f59e0b';
      statusText.textContent = 'オフライン動作中';
    }
  }

  // エラー表示
  function showError(message) {
    errorList.innerHTML = `<div style="margin-bottom: 4px;">${new Date().toLocaleString()}: ${message}</div>` + errorList.innerHTML;
    errorNotifications.style.display = 'block';
  }

  // 自動保存処理
  let autoSaveInterval;
  function startAutoSave() {
    if (autoSaveInterval) clearInterval(autoSaveInterval);

    autoSaveInterval = setInterval(async () => {
      try {
        // 作業記録の自動保存をシミュレート
        const now = new Date().toLocaleString();
        lastSaveTime.textContent = now;

        // ローカルストレージに保存
        if (settings.localSave === 'enabled') {
          const localData = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || '{}');
          localData['作業記録'] = {
            data: tables[1]?.records || [],
            lastUpdate: now,
            synced: navigator.onLine
          };
          localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(localData));
          renderLocalData();
        }

        statusIndicator.style.background = '#22c55e';
        statusText.textContent = '正常動作中';

      } catch (error) {
        console.error('自動保存エラー:', error);
        statusIndicator.style.background = '#ef4444';
        statusText.textContent = '保存エラー';
        showError('自動保存に失敗しました');
      }
    }, settings.interval * 1000);
  }

  // 設定保存
  container.querySelector('#btn-save-settings').addEventListener('click', () => {
    const interval = parseInt(container.querySelector('#save-interval').value);
    const localSave = container.querySelector('#local-save').value;

    settings = { interval, localSave };
    localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));

    // 自動保存間隔の更新
    startAutoSave();

    alert('設定を保存しました');
  });

  // 手動同期
  container.querySelector('#btn-sync').addEventListener('click', async () => {
    try {
      const localData = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || '{}');
      let syncCount = 0;

      for (const [key, data] of Object.entries(localData)) {
        if (!data.synced && Array.isArray(data.data)) {
          // 作業記録の同期
          for (const record of data.data) {
            if (!record.synced) {
              const saved = await window.aivicApi.save(1, record);
              if (saved) {
                record.synced = true;
                syncCount++;
              }
            }
          }
          data.synced = true;
        }
      }

      localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(localData));
      renderLocalData();

      alert(`${syncCount}件のデータを同期しました`);

    } catch (error) {
      console.error('同期エラー:', error);
      showError('データ同期に失敗しました');
    }
  });

  // ローカルデータ削除
  container.querySelector('#btn-clear-local').addEventListener('click', () => {
    if (confirm('ローカル保存データを削除しますか？\n※同期されていないデータは失われます。')) {
      localStorage.removeItem(LOCAL_STORAGE_KEY);
      renderLocalData();
      alert('ローカルデータを削除しました');
    }
  });

  // データ復旧
  container.querySelector('#btn-recovery').addEventListener('click', async () => {
    const recoveryDate = container.querySelector('#recovery-date').value;
    if (!recoveryDate) {
      alert('復旧対象日を選択してください');
      return;
    }

    if (confirm(`${recoveryDate}のデータを復旧しますか？`)) {
      try {
        // 指定日のデータを取得（実際の実装では日付フィルタリング）
        const records = await window.aivicApi.list(1);
        const targetRecords = records?.filter(r => 
          r.作業日 && r.作業日.startsWith(recoveryDate)
        ) || [];

        // ローカルストレージに復旧データを保存
        const localData = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || '{}');
        localData[`復旧データ_${recoveryDate}`] = {
          data: targetRecords,
          lastUpdate: new Date().toLocaleString(),
          synced: false
        };
        localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(localData));

        renderLocalData();
        alert(`${targetRecords.length}件のデータを復旧しました`);

      } catch (error) {
        console.error('復旧エラー:', error);
        showError('データ復旧に失敗しました');
      }
    }
  });

  // バックアップ作成
  container.querySelector('#btn-backup').addEventListener('click', async () => {
    try {
      const records = await window.aivicApi.list(1);
      if (!records) {
        showError('バックアップデータの取得に失敗しました');
        return;
      }

      const backup = {
        timestamp: new Date().toISOString(),
        records: records
      };

      const blob = new Blob([JSON.stringify(backup, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `work_records_backup_${new Date().toISOString().split('T')[0]}.json`;
      a.click();
      URL.revokeObjectURL(url);

      alert('バックアップファイルをダウンロードしました');

    } catch (error) {
      console.error('バックアップエラー:', error);
      showError('バックアップ作成に失敗しました');
    }
  });

  // イベントデリゲーション（個別同期）
  container.addEventListener('click', async (e) => {
    const syncBtn = e.target.closest('.sync-btn');
    if (syncBtn) {
      const key = syncBtn.dataset.key;
      try {
        const localData = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || '{}');
        if (localData[key] && !localData[key].synced) {
          // 同期処理（簡略化）
          localData[key].synced = true;
          localData[key].lastUpdate = new Date().toLocaleString();
          localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(localData));
          renderLocalData();
          alert(`${key}を同期しました`);
        }
      } catch (error) {
        console.error('同期エラー:', error);
        showError(`${key}の同期に失敗しました`);
      }
    }
  });

  // ネットワーク状態監視
  window.addEventListener('online', checkNetworkStatus);
  window.addEventListener('offline', checkNetworkStatus);

  // 設定値の復元
  container.querySelector('#save-interval').value = settings.interval;
  container.querySelector('#local-save').value = settings.localSave;

  // 初期化
  checkNetworkStatus();
  renderLocalData();
  startAutoSave();

  // 復旧対象日のデフォルト値設定
  container.querySelector('#recovery-date').value = new Date().toISOString().split('T')[0];
}

function(container, apiUrl, tables) {
  // 現在のユーザーIDを取得（実際の実装では認証情報から取得）
  const currentUserId = localStorage.getItem('currentUserId') || 'user-001';

  // 中断記録データを取得する関数
  async function getBreakTime(workRecordId) {
    try {
      const breakRecords = await window.aivicApi.list(2); // 中断記録テーブル
      if (!breakRecords) return 0;

      const relatedBreaks = breakRecords.filter(br => br.作業記録ID === workRecordId);
      return relatedBreaks.reduce((total, br) => total + (br.中断時間 || 0), 0);
    } catch (error) {
      return 0;
    }
  }

  // 異常値警告を取得する関数
  async function getAnomalyWarning(workRecordId) {
    try {
      const anomalies = await window.aivicApi.list(4); // 異常値検出ログテーブル
      if (!anomalies) return '';

      const relatedAnomalies = anomalies.filter(a => 
        a.検出対象レコードID === workRecordId && a.確認状況 === '未確認'
      );

      if (relatedAnomalies.length > 0) {
        const highPriority = relatedAnomalies.find(a => a.重要度 === '高');
        return highPriority ? '⚠️' : '⚡';
      }
      return '';
    } catch (error) {
      return '';
    }
  }

  // 時間フォーマット関数
  function formatTime(timestamp) {
    if (!timestamp) return '-';
    const date = new Date(timestamp);
    return date.toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });
  }

  // 日付フォーマット関数
  function formatDate(timestamp) {
    if (!timestamp) return '-';
    const date = new Date(timestamp);
    return date.toLocaleDateString('ja-JP');
  }

  // 作業時間フォーマット関数
  function formatDuration(minutes) {
    if (!minutes) return '-';
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return `${hours}h${mins.toString().padStart(2, '0')}m`;
  }

  // 承認状態のバッジスタイル
  function getApprovalBadge(status) {
    const styles = {
      '未承認': 'background: rgba(255, 193, 7, 0.15); color: #856404; padding: 2px 6px; border-radius: 4px; font-size: 11px;',
      '承認済み': 'background: rgba(40, 167, 69, 0.15); color: #155724; padding: 2px 6px; border-radius: 4px; font-size: 11px;',
      '差し戻し': 'background: rgba(220, 53, 69, 0.15); color: #721c24; padding: 2px 6px; border-radius: 4px; font-size: 11px;'
    };
    return `<span style="${styles[status] || styles['未承認']}">${status}</span>`;
  }

  // 進捗状況のバッジスタイル
  function getProgressBadge(status) {
    const styles = {
      '作業中': 'background: rgba(23, 162, 184, 0.15); color: #0c5460; padding: 2px 6px; border-radius: 4px; font-size: 11px;',
      '完了': 'background: rgba(40, 167, 69, 0.15); color: #155724; padding: 2px 6px; border-radius: 4px; font-size: 11px;',
      '中断': 'background: rgba(255, 193, 7, 0.15); color: #856404; padding: 2px 6px; border-radius: 4px; font-size: 11px;'
    };
    return `<span style="${styles[status] || styles['作業中']}">${status}</span>`;
  }

  // テーブル再描画関数
  async function renderRows(rows) {
    const tbody = container.querySelector('#records-tbody');
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="11" style="text-align: center; color: var(--text-muted);">記録がありません</td></tr>';
      return;
    }

    // 各行の中断時間と異常値警告を並行取得
    const rowsWithExtra = await Promise.all(rows.map(async (row) => {
      const [breakTime, warning] = await Promise.all([
        getBreakTime(row.作業記録ID),
        getAnomalyWarning(row.作業記録ID)
      ]);
      return { ...row, breakTime, warning };
    }));

    tbody.innerHTML = rowsWithExtra.map(row => `
      <tr data-id="${row.作業記録ID}">
        <td>${formatDate(row.作業日)}</td>
        <td>${row.プロジェクト名 || ''}</td>
        <td>${row.作業種別 || ''}</td>
        <td>${formatTime(row.作業開始時刻)}</td>
        <td>${formatTime(row.作業終了時刻)}</td>
        <td>${formatDuration(row.作業時間)}</td>
        <td>${formatDuration(row.breakTime)}</td>
        <td>${getProgressBadge(row.進捗状況)}</td>
        <td>${getApprovalBadge(row.承認状態)}</td>
        <td style="text-align: center;">${row.warning}</td>
        <td>
          <button class="action-btn secondary edit-btn" data-id="${row.作業記録ID}" style="margin-right: 4px;">修正</button>
          <button class="action-btn secondary delete-btn" data-id="${row.作業記録ID}">削除</button>
        </td>
      </tr>
    `).join('');
  }

  // 初期データ読み込み（現在のユーザーの記録のみ）
  window.aivicApi.list(1).then(allRecords => {
    if (allRecords) {
      const userRecords = allRecords.filter(record => record.作業員ID === currentUserId);
      renderRows(userRecords);
    } else {
      renderRows([]);
    }
  });

  // 検索ボタンのイベントリスナー
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const dateFrom = container.querySelector('#input-date-from').value;
    const dateTo = container.querySelector('#input-date-to').value;
    const projectFilter = container.querySelector('#input-project').value.toLowerCase();

    const allRecords = await window.aivicApi.list(1);
    if (!allRecords) return;

    let filteredRecords = allRecords.filter(record => record.作業員ID === currentUserId);

    // 日付フィルター
    if (dateFrom) {
      const fromDate = new Date(dateFrom);
      filteredRecords = filteredRecords.filter(record => {
        const recordDate = new Date(record.作業日);
        return recordDate >= fromDate;
      });
    }

    if (dateTo) {
      const toDate = new Date(dateTo);
      toDate.setHours(23, 59, 59, 999); // 終了日の23:59:59まで含める
      filteredRecords = filteredRecords.filter(record => {
        const recordDate = new Date(record.作業日);
        return recordDate <= toDate;
      });
    }

    // プロジェクトフィルター
    if (projectFilter) {
      filteredRecords = filteredRecords.filter(record => 
        (record.プロジェクト名 || '').toLowerCase().includes(projectFilter)
      );
    }

    renderRows(filteredRecords);
  });

  // CSVエクスポートボタン
  container.querySelector('#btn-export').addEventListener('click', async () => {
    const allRecords = await window.aivicApi.list(1);
    if (!allRecords) return;

    const userRecords = allRecords.filter(record => record.作業員ID === currentUserId);

    const headers = ['作業日', 'プロジェクト名', '作業種別', '開始時刻', '終了時刻', '作業時間(分)', '作業場所', '作業内容', '進捗状況', '承認状態', '備考'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...userRecords.map(record => [
        formatDate(record.作業日),
        `"${(record.プロジェクト名 || '').replace(/"/g, '""')}"`,
        `"${(record.作業種別 || '').replace(/"/g, '""')}"`,
        formatTime(record.作業開始時刻),
        formatTime(record.作業終了時刻),
        record.作業時間 || 0,
        `"${(record.作業場所 || '').replace(/"/g, '""')}"`,
        `"${(record.作業内容 || '').replace(/"/g, '""')}"`,
        record.進捗状況 || '',
        record.承認状態 || '',
        `"${(record.備考 || '').replace(/"/g, '""')}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `作業記録_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // メニューに戻るボタン
  container.querySelector('#btn-back').addEventListener('click', () => {
    window.showScreen('scr-1778907133295');
  });

  // 行レベル操作のイベントデリゲーション
  container.addEventListener('click', async (e) => {
    // 削除ボタン
    const deleteBtn = e.target.closest('.delete-btn');
    if (deleteBtn) {
      if (!confirm('この作業記録を削除しますか？')) return;

      const recordId = deleteBtn.dataset.id;
      const result = await window.aivicApi.delete(1, recordId);
      if (result !== null) {
        // 削除成功後、リストを再読み込み
        const allRecords = await window.aivicApi.list(1);
        if (allRecords) {
          const userRecords = allRecords.filter(record => record.作業員ID === currentUserId);
          renderRows(userRecords);
        }
      }
      return;
    }

    // 修正ボタン
    const editBtn = e.target.closest('.edit-btn');
    if (editBtn) {
      const recordId = editBtn.dataset.id;
      // 修正画面に遷移（レコードIDをローカルストレージに保存）
      localStorage.setItem('editRecordId', recordId);
      window.showScreen('scr-1778907343735');
      return;
    }
  });

  // 今日の日付を初期値として設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#input-date-from').value = today;
  container.querySelector('#input-date-to').value = today;
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#interruption-tbody");
  let timeInterval = null;
  let startTime = null;

  // 時間表示更新
  function updateElapsedTime() {
    if (startTime) {
      const now = new Date();
      const diff = Math.floor((now - startTime) / 1000 / 60);
      const hours = Math.floor(diff / 60);
      const minutes = diff % 60;
      container.querySelector("#time-display").textContent = 
        `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}`;
    }
  }

  // 中断開始時刻変更時の処理
  container.querySelector("#start-time").addEventListener("change", function() {
    if (this.value) {
      startTime = new Date(this.value);
      if (timeInterval) clearInterval(timeInterval);
      timeInterval = setInterval(updateElapsedTime, 60000);
      updateElapsedTime();
    }
  });

  // 現在時刻を初期値として設定
  const now = new Date();
  now.setSeconds(0, 0);
  container.querySelector("#start-time").value = now.toISOString().slice(0, 16);
  startTime = now;
  timeInterval = setInterval(updateElapsedTime, 60000);
  updateElapsedTime();

  // 関連作業項目表示の更新
  async function updateWorkItemDisplay() {
    try {
      const workRecords = await window.aivicApi.list(1); // 作業記録テーブル
      const currentWork = workRecords?.find(r => r.進捗状況 === "作業中");
      const display = container.querySelector("#work-item-display");
      if (currentWork) {
        display.textContent = `${currentWork.プロジェクト名} - ${currentWork.作業種別}`;
        display.style.color = "var(--text)";
      } else {
        display.textContent = "進行中の作業項目がありません";
        display.style.color = "var(--text-muted)";
      }
    } catch (error) {
      console.error("作業項目の取得に失敗:", error);
    }
  }

  // テーブル再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id || ''}">
        <td>${r.中断開始日時 ? new Date(r.中断開始日時).toLocaleString() : ""}</td>
        <td>${r.中断理由区分 || ""}</td>
        <td>${r.中断時間 ? Math.floor(r.中断時間 / 60) + "h" + (r.中断時間 % 60) + "m" : ""}</td>
        <td>
          <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; 
            ${r.影響度 === '重大' ? 'background: rgba(220, 38, 38, 0.1); color: #dc2626;' : 
              r.影響度 === '中程度' ? 'background: rgba(245, 158, 11, 0.1); color: #f59e0b;' : 
              'background: rgba(34, 197, 94, 0.1); color: #22c55e;'}">
            ${r.影響度 || ""}
          </span>
        </td>
        <td>${r.対応状況 || ""}</td>
        <td>
          <button class="action-btn secondary edit-btn" data-id="${r.id || ''}" style="font-size: 11px; padding: 4px 8px;">編集</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id || ''}" style="font-size: 11px; padding: 4px 8px; margin-left: 4px;">削除</button>
        </td>
      </tr>
    `).join("");
  }

  // 初期データ表示
  renderRows(tables[2]?.records || []);
  updateWorkItemDisplay();

  // 一時保存ボタン
  container.querySelector("#btn-temp-save").addEventListener("click", async function() {
    const formData = collectFormData();
    if (!formData.中断開始日時) {
      alert("中断開始時刻を入力してください");
      return;
    }

    formData.対応状況 = "対応中";

    const saved = await window.aivicApi.save(2, formData);
    if (saved) {
      alert("一時保存しました");
      const rows = await window.aivicApi.list(2);
      if (rows) renderRows(rows);
    }
  });

  // 記録完了ボタン
  container.querySelector("#btn-complete").addEventListener("click", async function() {
    const formData = collectFormData();
    if (!formData.中断開始日時 || !formData.中断理由区分) {
      alert("必須項目を入力してください");
      return;
    }

    // 中断終了時刻を現在時刻に設定
    formData.中断終了日時 = new Date().toISOString();
    formData.対応状況 = "解決済み";

    // 中断時間を計算
    const start = new Date(formData.中断開始日時);
    const end = new Date(formData.中断終了日時);
    formData.中断時間 = Math.floor((end - start) / 1000 / 60);

    const saved = await window.aivicApi.save(2, formData);
    if (saved) {
      alert("中断記録を完了しました");
      window.showScreen("scr-1778907251446");
    }
  });

  // フォームデータ収集
  function collectFormData() {
    const urgency = container.querySelector('input[name="urgency"]:checked')?.value || "中";
    const impacts = Array.from(container.querySelectorAll('input[type="checkbox"]:checked'))
      .map(cb => cb.value).join(", ");

    return {
      中断開始日時: container.querySelector("#start-time").value,
      中断理由区分: container.querySelector("#reason-category").value,
      中断理由詳細: container.querySelector("#reason-detail").value,
      影響度: urgency === "高" ? "重大" : urgency === "中" ? "中程度" : "軽微",
      記録者ID: "current-user-id" // 実際の実装では現在のユーザーIDを使用
    };
  }

  // 写真添付ボタン
  container.querySelector("#btn-photo").addEventListener("click", function() {
    const input = document.createElement("input");
    input.type = "file";
    input.accept = "image/*";
    input.onchange = function(e) {
      if (e.target.files.length > 0) {
        alert(`写真「${e.target.files[0].name}」を添付しました`);
      }
    };
    input.click();
  });

  // 音声メモボタン
  container.querySelector("#btn-voice").addEventListener("click", function() {
    alert("音声メモ機能は開発中です");
  });

  // 行レベル操作（編集・削除）
  container.addEventListener("click", async function(e) {
    const deleteBtn = e.target.closest(".delete-btn");
    const editBtn = e.target.closest(".edit-btn");

    if (deleteBtn) {
      if (!confirm("この中断記録を削除しますか？")) return;
      await window.aivicApi.delete(2, deleteBtn.dataset.id);
      const rows = await window.aivicApi.list(2);
      if (rows) renderRows(rows);
    }

    if (editBtn) {
      const id = editBtn.dataset.id;
      const rows = await window.aivicApi.list(2);
      const record = rows?.find(r => r.id === id);
      if (record) {
        // フォームに既存データを設定
        container.querySelector("#start-time").value = record.中断開始日時?.slice(0, 16) || "";
        container.querySelector("#reason-category").value = record.中断理由区分 || "";
        container.querySelector("#reason-detail").value = record.中断理由詳細 || "";

        // 緊急度設定
        const urgencyMap = {"重大": "高", "中程度": "中", "軽微": "低"};
        const urgencyValue = urgencyMap[record.影響度] || "中";
        const urgencyRadio = container.querySelector(`input[name="urgency"][value="${urgencyValue}"]`);
        if (urgencyRadio) urgencyRadio.checked = true;
      }
    }
  });

  // クリーンアップ
  return function cleanup() {
    if (timeInterval) {
      clearInterval(timeInterval);
    }
  };
}

function(container, apiUrl, tables) {
  let selectedWorkRecord = null;
  let selectedSuspendRecord = null;

  // 中断中作業の再描画
  function renderSuspendedWorks(workRecords, suspendRecords) {
    const tbody = container.querySelector("#suspended-work-tbody");

    // 中断中の作業記録を抽出（進捗状況が「中断」で、対応する中断記録の終了日時がnull）
    const suspendedWorks = workRecords.filter(work => 
      work.進捗状況 === "中断" && 
      suspendRecords.some(suspend => 
        suspend.作業記録ID === work.作業記録ID && !suspend.中断終了日時
      )
    );

    tbody.innerHTML = suspendedWorks.map(work => {
      const suspendRecord = suspendRecords.find(s => 
        s.作業記録ID === work.作業記録ID && !s.中断終了日時
      );

      const suspendStart = suspendRecord ? new Date(suspendRecord.中断開始日時).toLocaleString() : "";
      const suspendReason = suspendRecord ? suspendRecord.中断理由区分 : "";
      const suspendDuration = suspendRecord && suspendRecord.中断時間 ? `${suspendRecord.中断時間}分` : "計算中";

      return `
        <tr data-work-id="${work.作業記録ID}" data-suspend-id="${suspendRecord?.中断記録ID || ''}">
          <td>${work.作業内容 || ""}</td>
          <td>${work.プロジェクト名 || ""}</td>
          <td>${suspendStart}</td>
          <td>${suspendReason}</td>
          <td>${suspendDuration}</td>
          <td>
            <button class="action-btn resume-btn" data-work-id="${work.作業記録ID}" data-suspend-id="${suspendRecord?.中断記録ID || ''}">再開</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 初期データ読み込み
  async function loadData() {
    try {
      const workRecords = await window.aivicApi.list(1); // 作業記録
      const suspendRecords = await window.aivicApi.list(2); // 中断記録

      if (workRecords && suspendRecords) {
        renderSuspendedWorks(workRecords, suspendRecords);
      }
    } catch (error) {
      console.error("データ読み込みエラー:", error);
    }
  }

  // 現在時刻を再開時刻にセット
  function setCurrentTime() {
    const now = new Date();
    const localDateTime = new Date(now.getTime() - now.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
    container.querySelector("#resume-time").value = localDateTime;
  }

  // 作業再開フォーム表示
  function showResumeForm(workRecord, suspendRecord) {
    selectedWorkRecord = workRecord;
    selectedSuspendRecord = suspendRecord;

    container.querySelector("#selected-work-name").textContent = workRecord.作業内容 || "";
    container.querySelector("#suspend-start-time").textContent = suspendRecord ? new Date(suspendRecord.中断開始日時).toLocaleString() : "";
    container.querySelector("#suspend-reason").textContent = suspendRecord ? suspendRecord.中断理由区分 : "";

    setCurrentTime();

    container.querySelector("#resume-form").classList.remove("hidden");
  }

  // 作業再開フォーム非表示
  function hideResumeForm() {
    selectedWorkRecord = null;
    selectedSuspendRecord = null;
    container.querySelector("#resume-form").classList.add("hidden");

    // フォームリセット
    container.querySelector("#resume-time").value = "";
    container.querySelector("#resume-reason-category").value = "";
    container.querySelector("#resume-reason-detail").value = "";
  }

  // 確認ダイアログ表示
  function showConfirmDialog() {
    const workName = selectedWorkRecord?.作業内容 || "";
    const resumeTime = container.querySelector("#resume-time").value;
    const reasonCategory = container.querySelector("#resume-reason-category").value;
    const reasonDetail = container.querySelector("#resume-reason-detail").value;

    const content = `
      <div><strong>作業項目:</strong> ${workName}</div>
      <div><strong>再開時刻:</strong> ${new Date(resumeTime).toLocaleString()}</div>
      <div><strong>再開理由:</strong> ${reasonCategory}</div>
      ${reasonDetail ? `<div><strong>詳細:</strong> ${reasonDetail}</div>` : ""}
      <br>
      <div>この内容で作業を再開しますか？</div>
    `;

    container.querySelector("#confirm-content").innerHTML = content;
    container.querySelector("#confirm-dialog").classList.remove("hidden");
  }

  // 確認ダイアログ非表示
  function hideConfirmDialog() {
    container.querySelector("#confirm-dialog").classList.add("hidden");
  }

  // 作業再開処理
  async function resumeWork() {
    try {
      const resumeTime = container.querySelector("#resume-time").value;
      const reasonCategory = container.querySelector("#resume-reason-category").value;
      const reasonDetail = container.querySelector("#resume-reason-detail").value;

      if (!resumeTime || !reasonCategory) {
        alert("再開時刻と再開理由区分は必須です。");
        return;
      }

      // 中断記録を更新（終了時刻を設定）
      if (selectedSuspendRecord) {
        const suspendStartTime = new Date(selectedSuspendRecord.中断開始日時);
        const resumeDateTime = new Date(resumeTime);
        const suspendDuration = Math.floor((resumeDateTime - suspendStartTime) / (1000 * 60)); // 分単位

        await window.aivicApi.update(2, selectedSuspendRecord.中断記録ID, {
          中断終了日時: resumeTime,
          中断時間: suspendDuration,
          対応状況: "解決済み"
        });
      }

      // 作業記録を更新（進捗状況を「作業中」に変更）
      await window.aivicApi.update(1, selectedWorkRecord.作業記録ID, {
        進捗状況: "作業中"
      });

      hideConfirmDialog();
      hideResumeForm();

      // 画面遷移
      window.showScreen("scr-1778907296658"); // 工数入力画面

    } catch (error) {
      console.error("作業再開エラー:", error);
      alert("作業再開に失敗しました。");
    }
  }

  // イベントリスナー
  container.addEventListener("click", async (e) => {
    // 再開ボタン
    const resumeBtn = e.target.closest(".resume-btn");
    if (resumeBtn) {
      const workId = resumeBtn.dataset.workId;
      const suspendId = resumeBtn.dataset.suspendId;

      try {
        const workRecords = await window.aivicApi.list(1);
        const suspendRecords = await window.aivicApi.list(2);

        const workRecord = workRecords?.find(w => w.作業記録ID === workId);
        const suspendRecord = suspendRecords?.find(s => s.中断記録ID === suspendId);

        if (workRecord) {
          showResumeForm(workRecord, suspendRecord);
        }
      } catch (error) {
        console.error("データ取得エラー:", error);
      }
      return;
    }

    // キャンセルボタン
    if (e.target.id === "btn-cancel") {
      hideResumeForm();
      return;
    }

    // 作業再開ボタン
    if (e.target.id === "btn-resume") {
      showConfirmDialog();
      return;
    }

    // 確認ダイアログのキャンセル
    if (e.target.id === "btn-confirm-cancel") {
      hideConfirmDialog();
      return;
    }

    // 確認ダイアログのOK
    if (e.target.id === "btn-confirm-ok") {
      await resumeWork();
      return;
    }

    // 戻るボタン
    if (e.target.id === "btn-back") {
      window.history.back();
      return;
    }
  });

  // 初期データ読み込み
  loadData();
}

function(container, apiUrl, tables) {
  let currentData = [];

  // 1. 再描画関数の定義
  function renderValidationResults(rows) {
    const tbody = container.querySelector('#validation-results');
    tbody.innerHTML = rows.map(row => {
      const severityColor = row.重要度 === '高' ? '#ef4444' : row.重要度 === '中' ? '#f59e0b' : '#22c55e';
      const statusColor = row.確認状況 === '未確認' ? '#ef4444' : row.確認状況 === '確認済み' ? '#f59e0b' : '#22c55e';

      return `
        <tr data-id="${row.id || ''}">
          <td><span style="display: inline-block; padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 500; background: ${severityColor}20; color: ${severityColor};">${row.重要度 || ''}</span></td>
          <td style="font-size: 12px; color: var(--text);">${row.異常値種別 || ''}</td>
          <td style="font-size: 12px; color: var(--text);">${row.検出項目 || ''}</td>
          <td style="font-size: 12px; color: var(--text); font-weight: 500;">${row.検出値 || ''}</td>
          <td style="font-size: 12px; color: var(--text-muted);">${row.閾値 || ''}</td>
          <td style="font-size: 12px; color: var(--text);">${row.作業員名 || ''}</td>
          <td style="font-size: 12px; color: var(--text-muted);">${row.検出日時 ? new Date(row.検出日時).toLocaleString('ja-JP', {month:'2-digit', day:'2-digit', hour:'2-digit', minute:'2-digit'}) : ''}</td>
          <td><span style="display: inline-block; padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 500; background: ${statusColor}20; color: ${statusColor};">${row.確認状況 || ''}</span></td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${row.id || ''}" style="padding: 4px 8px; font-size: 11px;">詳細</button>
          </td>
        </tr>
      `;
    }).join('');

    updateStatusCounts(rows);
    updateSaveStatus(rows);
  }

  function updateStatusCounts(rows) {
    const validCount = rows.filter(r => r.重要度 === '低' && r.確認状況 === '対応済み').length;
    const warningCount = rows.filter(r => r.重要度 === '中').length;
    const errorCount = rows.filter(r => r.重要度 === '高').length;

    container.querySelector('#count-valid').textContent = validCount;
    container.querySelector('#count-warning').textContent = warningCount;
    container.querySelector('#count-error').textContent = errorCount;
  }

  function updateSaveStatus(rows) {
    const hasErrors = rows.some(r => r.重要度 === '高' && r.確認状況 === '未確認');
    const indicator = container.querySelector('#save-indicator');
    const message = container.querySelector('#save-message');

    if (hasErrors) {
      indicator.style.background = '#ef4444';
      message.textContent = '保存不可（重大エラーあり）';
      message.style.color = '#ef4444';
    } else {
      indicator.style.background = '#22c55e';
      message.textContent = '保存可能';
      message.style.color = '#22c55e';
    }
  }

  // 2. 初期データ読み込み
  async function loadData() {
    try {
      const rows = await window.aivicApi.list(4); // 異常値検出ログテーブル
      if (rows) {
        currentData = rows;
        renderValidationResults(rows);
      } else {
        currentData = tables[4]?.records || [];
        renderValidationResults(currentData);
      }
    } catch (error) {
      console.error('データ読み込みエラー:', error);
      currentData = tables[4]?.records || [];
      renderValidationResults(currentData);
    }
  }

  loadData();

  // 3. 検索機能
  container.querySelector('#btn-search').addEventListener('click', () => {
    const keyword = container.querySelector('#search-keyword').value.toLowerCase();
    const severity = container.querySelector('#filter-severity').value;

    let filtered = currentData;

    if (keyword) {
      filtered = filtered.filter(row => 
        JSON.stringify(row).toLowerCase().includes(keyword)
      );
    }

    if (severity) {
      filtered = filtered.filter(row => row.重要度 === severity);
    }

    renderValidationResults(filtered);
  });

  // 4. 最新状態に更新
  container.querySelector('#btn-refresh').addEventListener('click', loadData);

  // 5. エラーログ出力
  container.querySelector('#btn-export-log').addEventListener('click', () => {
    const headers = ['重要度', '異常値種別', '検出項目', '検出値', '閾値', '作業員名', '検出日時', '確認状況', '対応メモ'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...currentData.map(row => [
        row.重要度 || '',
        row.異常値種別 || '',
        row.検出項目 || '',
        row.検出値 || '',
        row.閾値 || '',
        row.作業員名 || '',
        row.検出日時 || '',
        row.確認状況 || '',
        (row.対応メモ || '').replace(/,/g, '，')
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `validation_errors_${new Date().toISOString().slice(0,10)}.csv`;
    link.click();
  });

  // 6. イベントデリゲーション（詳細表示・確認済み処理）
  container.addEventListener('click', async (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      const row = currentData.find(r => r.id === id);
      if (row) {
        showDetailModal(row);
      }
      return;
    }
  });

  // モーダル関連
  function showDetailModal(row) {
    const modal = container.querySelector('#detail-modal');
    const content = container.querySelector('#modal-content');

    content.innerHTML = `
      <div style="margin-bottom: 12px;">
        <strong>異常値種別:</strong> ${row.異常値種別 || ''}<br>
        <strong>検出項目:</strong> ${row.検出項目 || ''}<br>
        <strong>検出値:</strong> ${row.検出値 || ''} (閾値: ${row.閾値 || ''})<br>
        <strong>重要度:</strong> ${row.重要度 || ''}<br>
        <strong>作業員:</strong> ${row.作業員名 || ''}<br>
        <strong>検出日時:</strong> ${row.検出日時 ? new Date(row.検出日時).toLocaleString('ja-JP') : ''}<br>
        <strong>確認状況:</strong> ${row.確認状況 || ''}
      </div>
      ${row.対応メモ ? `<div style="margin-bottom: 12px;"><strong>対応メモ:</strong><br>${row.対応メモ}</div>` : ''}
    `;

    modal.classList.remove('hidden');

    // 修正提案ボタン
    container.querySelector('#btn-fix-suggestion').onclick = () => {
      window.showScreen('scr-1778907319067'); // 修正入力画面
    };

    // 確認済みボタン
    container.querySelector('#btn-mark-confirmed').onclick = async () => {
      try {
        await window.aivicApi.update(4, row.id, {
          確認状況: '確認済み',
          確認者ID: 'current-user', // 実際の実装では現在のユーザーIDを使用
          確認日時: new Date().toISOString()
        });
        modal.classList.add('hidden');
        loadData();
      } catch (error) {
        console.error('更新エラー:', error);
      }
    };
  }

  // モーダルを閉じる
  container.querySelector('#btn-close-modal').addEventListener('click', () => {
    container.querySelector('#detail-modal').classList.add('hidden');
  });

  // モーダル背景クリックで閉じる
  container.querySelector('#detail-modal').addEventListener('click', (e) => {
    if (e.target === container.querySelector('#detail-modal')) {
      container.querySelector('#detail-modal').classList.add('hidden');
    }
  });
}

function(container, apiUrl, tables) {
  // エラー情報の初期化
  const errorInfo = {
    title: "システムエラーが発生しました",
    message: "申し訳ございませんが、システムで予期しないエラーが発生しました。",
    code: "ERR_500_001",
    timestamp: new Date().toLocaleString('ja-JP', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit'
    }).replace(/\//g, '/'),
    solution: [
      "1. 「再試行」ボタンをクリックして、もう一度お試しください",
      "2. 問題が解決しない場合は、ページを再読み込みしてください", 
      "3. それでも解決しない場合は、管理者にお問い合わせください"
    ],
    details: {
      url: window.location.pathname,
      method: "POST",
      status: "500",
      userAgent: navigator.userAgent.substring(0, 50) + "...",
      stack: "TypeError: Cannot read property 'id' of undefined\n    at WorkRecordService.save (work-record.service.js:45)\n    at async saveWorkRecord (work-record.controller.js:23)"
    }
  };

  // URLパラメータからエラー情報を取得（もしあれば）
  const urlParams = new URLSearchParams(window.location.search);
  if (urlParams.get('error')) {
    try {
      const errorData = JSON.parse(decodeURIComponent(urlParams.get('error')));
      Object.assign(errorInfo, errorData);
    } catch (e) {
      console.warn('エラー情報の解析に失敗しました:', e);
    }
  }

  // エラー情報を画面に反映
  container.querySelector('#error-title').textContent = errorInfo.title;
  container.querySelector('#error-message').textContent = errorInfo.message;
  container.querySelector('#error-code').textContent = errorInfo.code;
  container.querySelector('#error-timestamp').textContent = errorInfo.timestamp;

  // 対処方法の更新
  const solutionContainer = container.querySelector('#error-solution-text');
  solutionContainer.innerHTML = errorInfo.solution.map(step => 
    `<p style="margin: 0 0 6px 0;">${step}</p>`
  ).join('');

  // エラー詳細情報の更新
  container.querySelector('#error-url').textContent = errorInfo.details.url;
  container.querySelector('#error-method').textContent = errorInfo.details.method;
  container.querySelector('#error-status').textContent = errorInfo.details.status;
  container.querySelector('#error-user-agent').textContent = errorInfo.details.userAgent;
  container.querySelector('#error-stack').textContent = errorInfo.details.stack;

  // 再試行ボタン
  container.querySelector('#btn-retry').addEventListener('click', () => {
    // 前の画面に戻って再実行を試みる
    if (window.history.length > 1) {
      window.history.back();
    } else {
      window.showScreen('scr-1778907133295'); // 工数記録画面
    }
  });

  // 戻るボタン
  container.querySelector('#btn-back').addEventListener('click', () => {
    if (window.history.length > 1) {
      window.history.back();
    } else {
      window.showScreen('scr-1778907133295'); // 工数記録画面
    }
  });

  // ホームに戻るボタン
  container.querySelector('#btn-home').addEventListener('click', () => {
    window.showScreen('scr-1778907133295'); // 工数記録画面（メイン画面）
  });

  // 管理者に連絡ボタン
  container.querySelector('#btn-contact').addEventListener('click', () => {
    // 緊急報告画面に遷移してエラー情報を引き継ぐ
    const errorReport = {
      type: 'システムエラー',
      code: errorInfo.code,
      message: errorInfo.message,
      timestamp: errorInfo.timestamp,
      details: JSON.stringify(errorInfo.details, null, 2)
    };

    // 緊急報告画面にエラー情報をセッションストレージで渡す
    sessionStorage.setItem('errorReport', JSON.stringify(errorReport));
    window.showScreen('scr-1778907330826'); // 緊急報告画面
  });

  // エラー詳細表示切り替え
  const toggleDetailsBtn = container.querySelector('#btn-toggle-details');
  const detailsSection = container.querySelector('#error-details');
  let detailsVisible = false;

  toggleDetailsBtn.addEventListener('click', () => {
    detailsVisible = !detailsVisible;
    if (detailsVisible) {
      detailsSection.classList.remove('hidden');
      toggleDetailsBtn.textContent = 'エラー詳細を非表示';
    } else {
      detailsSection.classList.add('hidden');
      toggleDetailsBtn.textContent = 'エラー詳細を表示';
    }
  });

  // エラーログの記録（異常値検出ログテーブルに保存）
  const saveErrorLog = async () => {
    try {
      const currentUser = JSON.parse(sessionStorage.getItem('currentUser') || '{}');
      const errorLog = {
        検出対象テーブル: 'システムエラー',
        検出対象レコードID: 'system-error-' + Date.now(),
        ユーザーID: currentUser.ユーザーID || 'unknown',
        異常値種別: 'システムエラー',
        検出項目: 'エラーコード',
        検出値: errorInfo.code,
        閾値: 'N/A',
        重要度: '高',
        確認状況: '未確認',
        通知送信フラグ: true,
        検出日時: new Date().toISOString(),
        作成日時: new Date().toISOString(),
        更新日時: new Date().toISOString()
      };

      // 異常値検出ログテーブル（テーブルインデックス4）に保存
      await window.aivicApi.save(4, errorLog);
    } catch (e) {
      console.warn('エラーログの保存に失敗しました:', e);
    }
  };

  // 初期化時にエラーログを保存
  saveErrorLog();

  // キーボードショートカット
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      container.querySelector('#btn-back').click();
    } else if (e.key === 'Enter' && e.ctrlKey) {
      container.querySelector('#btn-retry').click();
    }
  });
}

function(container, apiUrl, tables) {
  let currentEditingId = null;

  // 重要度レベルのスタイル取得
  function getPriorityStyle(priority) {
    switch(priority) {
      case '高': return 'background: #dc3545; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;';
      case '中': return 'background: #ffc107; color: #000; padding: 2px 6px; border-radius: 4px; font-size: 11px;';
      case '低': return 'background: #28a745; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;';
      default: return 'background: var(--border); color: var(--text); padding: 2px 6px; border-radius: 4px; font-size: 11px;';
    }
  }

  // 確認状況のスタイル取得
  function getStatusStyle(status) {
    switch(status) {
      case '未確認': return 'background: #dc3545; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;';
      case '確認済み': return 'background: #ffc107; color: #000; padding: 2px 6px; border-radius: 4px; font-size: 11px;';
      case '対応済み': return 'background: #28a745; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;';
      default: return 'background: var(--border); color: var(--text); padding: 2px 6px; border-radius: 4px; font-size: 11px;';
    }
  }

  // 検証結果テーブル再描画
  function renderValidationResults(rows) {
    const tbody = container.querySelector("#validation-results");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}" style="height: 36px;">
        <td style="padding: 6px 10px;">
          <input type="checkbox" class="row-check" data-id="${r.id}" style="accent-color: var(--primary);">
        </td>
        <td style="padding: 6px 10px; font-size: 13px;">${new Date(r.検出日時).toLocaleString() || ""}</td>
        <td style="padding: 6px 10px; font-size: 13px;">${r.作業員名 || ""}</td>
        <td style="padding: 6px 10px; font-size: 13px;">${r.異常値種別 || ""}</td>
        <td style="padding: 6px 10px; font-size: 13px;">${r.検出項目 || ""}</td>
        <td style="padding: 6px 10px; font-size: 13px;">${r.検出値 || ""}</td>
        <td style="padding: 6px 10px; font-size: 13px;">${r.閾値 || ""}</td>
        <td style="padding: 6px 10px;">
          <span style="${getPriorityStyle(r.重要度)}">${r.重要度 || ""}</span>
        </td>
        <td style="padding: 6px 10px;">
          <span style="${getStatusStyle(r.確認状況)}">${r.確認状況 || ""}</span>
        </td>
        <td style="padding: 6px 10px;">
          <button class="action-btn secondary correct-btn" data-id="${r.id}" style="font-size: 11px; padding: 4px 8px; margin-right: 4px;">修正</button>
          <button class="action-btn secondary approve-btn" data-id="${r.id}" style="font-size: 11px; padding: 4px 8px;">承認</button>
        </td>
      </tr>
    `).join("");
  }

  // 初期データ描画
  renderValidationResults(tables[4]?.records || []);

  // 日付の初期値設定（過去7日間）
  const today = new Date();
  const weekAgo = new Date(today.getTime() - 7 * 24 * 60 * 60 * 1000);
  container.querySelector("#input-start-date").value = weekAgo.toISOString().split('T')[0];
  container.querySelector("#input-end-date").value = today.toISOString().split('T')[0];

  // 検証実行ボタン
  container.querySelector("#btn-validate").addEventListener("click", async () => {
    const startDate = container.querySelector("#input-start-date").value;
    const endDate = container.querySelector("#input-end-date").value;
    const errorType = container.querySelector("#select-error-type").value;

    if (!startDate || !endDate) {
      alert("検証期間を選択してください");
      return;
    }

    // 進捗表示開始
    const progressArea = container.querySelector("#progress-area");
    const progressBar = container.querySelector("#progress-bar");
    const progressText = container.querySelector("#progress-text");
    const statusText = container.querySelector("#validation-status");

    progressArea.classList.remove("hidden");
    statusText.textContent = "検証中...";

    // 進捗アニメーション
    let progress = 0;
    const progressInterval = setInterval(() => {
      progress += Math.random() * 15;
      if (progress > 90) progress = 90;
      progressBar.style.width = progress + "%";
      progressText.textContent = Math.round(progress) + "%";
    }, 200);

    try {
      // 異常値検出ログを取得
      const rows = await window.aivicApi.list(4);
      let filteredRows = rows || [];

      // 期間フィルタ
      filteredRows = filteredRows.filter(r => {
        const detectionDate = new Date(r.検出日時).toISOString().split('T')[0];
        return detectionDate >= startDate && detectionDate <= endDate;
      });

      // エラー種別フィルタ
      if (errorType) {
        filteredRows = filteredRows.filter(r => r.異常値種別 === errorType);
      }

      // 進捗完了
      setTimeout(() => {
        clearInterval(progressInterval);
        progressBar.style.width = "100%";
        progressText.textContent = "100%";
        statusText.textContent = "完了";

        renderValidationResults(filteredRows);

        // 完了通知
        const notificationArea = container.querySelector("#notification-area");
        const notificationText = container.querySelector("#notification-text");
        notificationText.textContent = `${filteredRows.length}件の異常値を検出しました。`;
        notificationArea.classList.remove("hidden");

        setTimeout(() => {
          progressArea.classList.add("hidden");
        }, 1000);
      }, 1000);

    } catch (error) {
      clearInterval(progressInterval);
      progressArea.classList.add("hidden");
      alert("検証処理でエラーが発生しました");
    }
  });

  // 全選択チェックボックス
  container.querySelector("#check-all").addEventListener("change", (e) => {
    const checkboxes = container.querySelectorAll(".row-check");
    checkboxes.forEach(cb => cb.checked = e.target.checked);
    updateBulkApproveButton();
  });

  // 一括承認チェックボックス
  container.querySelector("#check-bulk-approve").addEventListener("change", updateBulkApproveButton);

  function updateBulkApproveButton() {
    const bulkCheck = container.querySelector("#check-bulk-approve").checked;
    const selectedRows = container.querySelectorAll(".row-check:checked");
    const bulkBtn = container.querySelector("#btn-bulk-approve");
    bulkBtn.disabled = !bulkCheck || selectedRows.length === 0;
  }

  // 行選択時の一括承認ボタン更新
  container.addEventListener("change", (e) => {
    if (e.target.classList.contains("row-check")) {
      updateBulkApproveButton();
    }
  });

  // 一括承認ボタン
  container.querySelector("#btn-bulk-approve").addEventListener("click", async () => {
    const selectedRows = container.querySelectorAll(".row-check:checked");
    if (selectedRows.length === 0) return;

    if (!confirm(`${selectedRows.length}件の異常値を承認しますか？`)) return;

    try {
      for (const checkbox of selectedRows) {
        const id = checkbox.dataset.id;
        await window.aivicApi.update(4, id, { 確認状況: "対応済み", 確認日時: new Date().toISOString() });
      }

      const rows = await window.aivicApi.list(4);
      renderValidationResults(rows || []);

      // 選択解除
      container.querySelector("#check-all").checked = false;
      container.querySelector("#check-bulk-approve").checked = false;
      updateBulkApproveButton();

    } catch (error) {
      alert("一括承認処理でエラーが発生しました");
    }
  });

  // 修正・承認ボタンのイベントデリゲーション
  container.addEventListener("click", async (e) => {
    // 修正ボタン
    const correctBtn = e.target.closest(".correct-btn");
    if (correctBtn) {
      currentEditingId = correctBtn.dataset.id;
      const modal = container.querySelector("#correction-modal");
      modal.classList.remove("hidden");
      return;
    }

    // 承認ボタン
    const approveBtn = e.target.closest(".approve-btn");
    if (approveBtn) {
      if (!confirm("この異常値を承認しますか？")) return;

      try {
        await window.aivicApi.update(4, approveBtn.dataset.id, { 
          確認状況: "対応済み", 
          確認日時: new Date().toISOString() 
        });

        const rows = await window.aivicApi.list(4);
        renderValidationResults(rows || []);
      } catch (error) {
        alert("承認処理でエラーが発生しました");
      }
      return;
    }
  });

  // モーダル閉じる
  container.querySelector("#btn-close-modal").addEventListener("click", () => {
    container.querySelector("#correction-modal").classList.add("hidden");
  });

  container.querySelector("#btn-cancel-correction").addEventListener("click", () => {
    container.querySelector("#correction-modal").classList.add("hidden");
  });

  // 修正保存
  container.querySelector("#btn-save-correction").addEventListener("click", async () => {
    const startTime = container.querySelector("#modal-start-time").value;
    const endTime = container.querySelector("#modal-end-time").value;
    const reason = container.querySelector("#modal-reason").value;

    if (!startTime || !endTime || !reason) {
      alert("全ての項目を入力してください");
      return;
    }

    try {
      // 異常値ログを対応済みに更新
      await window.aivicApi.update(4, currentEditingId, { 
        確認状況: "対応済み", 
        確認日時: new Date().toISOString(),
        対応メモ: reason
      });

      // 作業記録も更新（実際の修正）
      // ここでは異常値ログの対象レコードIDを使って作業記録を更新
      const logRecord = await window.aivicApi.list(4);
      const targetLog = logRecord.find(r => r.id === currentEditingId);
      if (targetLog && targetLog.検出対象レコードID) {
        const workTime = Math.floor((new Date(endTime) - new Date(startTime)) / (1000 * 60));
        await window.aivicApi.update(1, targetLog.検出対象レコードID, {
          作業開始時刻: startTime,
          作業終了時刻: endTime,
          作業時間: workTime
        });
      }

      const rows = await window.aivicApi.list(4);
      renderValidationResults(rows || []);

      container.querySelector("#correction-modal").classList.add("hidden");

      // フォームリセット
      container.querySelector("#modal-start-time").value = "";
      container.querySelector("#modal-end-time").value = "";
      container.querySelector("#modal-reason").value = "";

    } catch (error) {
      alert("修正保存でエラーが発生しました");
    }
  });

  // 検証ログ出力
  container.querySelector("#btn-export-log").addEventListener("click", async () => {
    try {
      const rows = await window.aivicApi.list(4);
      if (!rows || rows.length === 0) {
        alert("出力するデータがありません");
        return;
      }

      const headers = ["検出日時", "作業員名", "異常値種別", "検出項目", "検出値", "閾値", "重要度", "確認状況", "対応メモ"];
      const csvContent = "\uFEFF" + [
        headers.join(","),
        ...rows.map(r => [
          r.検出日時 || "",
          r.作業員名 || "",
          r.異常値種別 || "",
          r.検出項目 || "",
          r.検出値 || "",
          r.閾値 || "",
          r.重要度 || "",
          r.確認状況 || "",
          r.対応メモ || ""
        ].map(field => `"${String(field).replace(/"/g, '""')}"`).join(","))
      ].join("\n");

      const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = `validation_log_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();

    } catch (error) {
      alert("ログ出力でエラーが発生しました");
    }
  });

  // 再検証ボタン
  container.querySelector("#btn-revalidate").addEventListener("click", () => {
    container.querySelector("#btn-validate").click();
  });
}

function(container, apiUrl, tables) {
  let currentWorkRecord = null;
  let interruptRecords = [];

  // 現在の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#work-date').value = today;

  // 作業項目マスタを読み込み
  function loadWorkItems() {
    const workItemSelect = container.querySelector('#work-item');
    const workItemsTable = tables.find(t => t.tableName === '作業項目マスタ');
    if (workItemsTable && workItemsTable.records) {
      workItemsTable.records.forEach(item => {
        if (item.有効フラグ) {
          const option = document.createElement('option');
          option.value = item.作業項目ID;
          option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
          workItemSelect.appendChild(option);
        }
      });
    }
  }

  // 実働時間を計算
  function calculateActualHours() {
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const breakTime = parseInt(container.querySelector('#break-time').value) || 0;

    if (startTime && endTime) {
      const start = new Date(`2000-01-01T${startTime}`);
      const end = new Date(`2000-01-01T${endTime}`);
      const diffMinutes = (end - start) / (1000 * 60) - breakTime;

      if (diffMinutes > 0) {
        const hours = Math.floor(diffMinutes / 60);
        const minutes = diffMinutes % 60;
        container.querySelector('#actual-hours').textContent = `${hours}時間${minutes}分`;
      } else {
        container.querySelector('#actual-hours').textContent = '0時間0分';
      }
    }
  }

  // 中断記録を表示
  function renderInterruptList() {
    const listContainer = container.querySelector('#interrupt-list');
    if (interruptRecords.length === 0) {
      listContainer.innerHTML = '<div style="color: var(--text-muted); font-size: 12px; text-align: center; padding: 8px;">中断記録なし</div>';
      return;
    }

    listContainer.innerHTML = interruptRecords.map(record => `
      <div style="background: var(--bg-main); border: 1px solid var(--border); border-radius: 4px; padding: 8px; margin-bottom: 6px;">
        <div style="font-size: 12px; font-weight: 500; color: var(--text); margin-bottom: 2px;">${record.中断理由区分}</div>
        <div style="font-size: 11px; color: var(--text-muted);">${record.中断時間}分</div>
      </div>
    `).join('');
  }

  // イベントリスナー設定
  container.querySelector('#start-time').addEventListener('change', calculateActualHours);
  container.querySelector('#end-time').addEventListener('change', calculateActualHours);
  container.querySelector('#break-time').addEventListener('input', calculateActualHours);

  // 記録保存
  container.querySelector('#btn-save').addEventListener('click', async () => {
    const workDate = container.querySelector('#work-date').value;
    const workItem = container.querySelector('#work-item').value;
    const workLocation = container.querySelector('#work-location').value;
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const breakTime = parseInt(container.querySelector('#break-time').value) || 0;
    const workDetail = container.querySelector('#work-detail').value;

    if (!workDate || !workItem || !workLocation || !startTime || !workDetail) {
      alert('必須項目を入力してください');
      return;
    }

    const workRecord = {
      作業員ID: 'current-user-id', // 実際のログインユーザーIDを使用
      作業日: new Date(workDate).toISOString(),
      作業開始時刻: new Date(`${workDate}T${startTime}`).toISOString(),
      作業終了時刻: endTime ? new Date(`${workDate}T${endTime}`).toISOString() : null,
      プロジェクト名: 'デフォルトプロジェクト',
      作業場所: workLocation,
      作業種別: container.querySelector('#work-item option:checked').textContent.split(' - ')[1] || '作業',
      作業内容: workDetail,
      進捗状況: endTime ? '完了' : '作業中',
      承認状態: '未承認',
      作成者ID: 'current-user-id'
    };

    const workRecordsTableIndex = tables.findIndex(t => t.tableName === '作業記録');
    const saved = await window.aivicApi.save(workRecordsTableIndex, workRecord);

    if (saved) {
      currentWorkRecord = saved;
      alert('作業記録を保存しました');
    }
  });

  // 中断記録追加
  container.querySelector('#btn-add-interrupt').addEventListener('click', async () => {
    const reason = container.querySelector('#interrupt-reason').value;
    const duration = parseInt(container.querySelector('#interrupt-duration').value);

    if (!reason || !duration) {
      alert('中断理由と時間を入力してください');
      return;
    }

    const interruptRecord = {
      作業記録ID: currentWorkRecord?.id || 'temp-work-record-id',
      中断開始日時: new Date().toISOString(),
      中断理由区分: reason,
      中断時間: duration,
      対応状況: '記録済み',
      記録者ID: 'current-user-id'
    };

    const interruptTableIndex = tables.findIndex(t => t.tableName === '中断記録');
    const saved = await window.aivicApi.save(interruptTableIndex, interruptRecord);

    if (saved) {
      interruptRecords.push(saved);
      renderInterruptList();
      container.querySelector('#interrupt-reason').value = '';
      container.querySelector('#interrupt-duration').value = '';
      alert('中断記録を追加しました');
    }
  });

  // 画面遷移
  container.querySelector('#btn-interrupt').addEventListener('click', () => {
    window.showScreen("scr-1778907238439");
  });

  container.querySelector('#btn-complete').addEventListener('click', () => {
    window.showScreen("scr-1778907199709");
  });

  // 初期化
  loadWorkItems();
  renderInterruptList();
}

function(container, apiUrl, tables) {
  let currentRecord = null;
  let workItems = [];
  let breakRecords = [];

  // 作業項目マスタを取得
  async function loadWorkItems() {
    const items = await window.aivicApi.list(3); // 作業項目マスタ
    if (items) {
      workItems = items.filter(item => item.有効フラグ);
      const select = container.querySelector("#select-work-item");
      select.innerHTML = '<option value="">選択してください</option>' +
        workItems.map(item => `<option value="${item.作業項目ID}">${item.作業項目名}</option>`).join("");
    }
  }

  // 作業記録一覧を取得してドロップダウンに設定
  async function loadWorkRecords() {
    const records = await window.aivicApi.list(1); // 作業記録
    if (records) {
      const select = container.querySelector("#select-record");
      select.innerHTML = '<option value="">選択してください</option>' +
        records.map(record => {
          const date = new Date(record.作業日).toLocaleDateString();
          const project = record.プロジェクト名 || '';
          const content = record.作業内容 ? record.作業内容.substring(0, 20) + '...' : '';
          return `<option value="${record.作業記録ID}">${date} - ${project} - ${content}</option>`;
        }).join("");
    }
  }

  // 修正前データを表示
  function displayOriginalData(record) {
    const originalDataDiv = container.querySelector("#original-data");
    if (!record) {
      originalDataDiv.innerHTML = '<div style="color: var(--text-muted);">記録を選択してください</div>';
      return;
    }

    const startTime = record.作業開始時刻 ? new Date(record.作業開始時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '-';
    const endTime = record.作業終了時刻 ? new Date(record.作業終了時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '-';
    const workDate = new Date(record.作業日).toLocaleDateString();

    originalDataDiv.innerHTML = `
      <div style="margin-bottom: 8px;"><strong>作業日:</strong> ${workDate}</div>
      <div style="margin-bottom: 8px;"><strong>開始時刻:</strong> ${startTime}</div>
      <div style="margin-bottom: 8px;"><strong>終了時刻:</strong> ${endTime}</div>
      <div style="margin-bottom: 8px;"><strong>作業時間:</strong> ${record.作業時間 || 0}分</div>
      <div style="margin-bottom: 8px;"><strong>プロジェクト:</strong> ${record.プロジェクト名 || '-'}</div>
      <div style="margin-bottom: 8px;"><strong>作業場所:</strong> ${record.作業場所 || '-'}</div>
      <div style="margin-bottom: 8px;"><strong>作業種別:</strong> ${record.作業種別 || '-'}</div>
      <div style="margin-bottom: 8px;"><strong>進捗状況:</strong> ${record.進捗状況 || '-'}</div>
      <div><strong>作業内容:</strong> ${record.作業内容 || '-'}</div>
    `;
  }

  // 中断記録を表示
  async function displayBreakRecords(workRecordId) {
    const breaks = await window.aivicApi.list(2); // 中断記録
    const breakRecordsDiv = container.querySelector("#break-records");

    if (breaks) {
      const relatedBreaks = breaks.filter(b => b.作業記録ID === workRecordId);
      if (relatedBreaks.length === 0) {
        breakRecordsDiv.innerHTML = 'なし';
      } else {
        breakRecordsDiv.innerHTML = relatedBreaks.map(b => {
          const startTime = new Date(b.中断開始日時).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'});
          const endTime = b.中断終了日時 ? new Date(b.中断終了日時).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '継続中';
          return `<div style="margin-bottom: 4px;">${startTime} - ${endTime} (${b.中断理由区分})</div>`;
        }).join("");
      }
      breakRecords = relatedBreaks;
    }
  }

  // 時間計算
  function calculateTimes() {
    const startTime = container.querySelector("#input-start-time").value;
    const endTime = container.querySelector("#input-end-time").value;
    const breakTime = container.querySelector("#input-break-time").value;

    let actualWorkTime = 0;
    let breakDuration = 0;

    if (startTime && endTime) {
      const start = new Date(`2000-01-01T${startTime}`);
      const end = new Date(`2000-01-01T${endTime}`);
      const totalMinutes = (end - start) / (1000 * 60);

      if (breakTime) {
        const breakStart = new Date(`2000-01-01T${breakTime}`);
        breakDuration = Math.max(0, (end - breakStart) / (1000 * 60));
      }

      actualWorkTime = Math.max(0, totalMinutes - breakDuration);
    }

    container.querySelector("#break-duration").textContent = `${breakDuration}分`;
    container.querySelector("#actual-work-time").textContent = `${actualWorkTime}分`;

    // 異常値チェック
    checkAnomalies(actualWorkTime, breakDuration);
  }

  // 異常値チェック
  function checkAnomalies(workTime, breakTime) {
    const warningArea = container.querySelector("#warning-area");
    const warningMessage = container.querySelector("#warning-message");
    let warnings = [];

    if (workTime > 480) { // 8時間超過
      warnings.push("作業時間が8時間を超えています");
    }
    if (workTime < 30 && workTime > 0) { // 30分未満
      warnings.push("作業時間が30分未満です");
    }
    if (breakTime > 120) { // 2時間超過
      warnings.push("中断時間が2時間を超えています");
    }

    if (warnings.length > 0) {
      warningMessage.textContent = warnings.join(", ");
      warningArea.classList.remove("hidden");
    } else {
      warningArea.classList.add("hidden");
    }
  }

  // 記録選択時の処理
  container.querySelector("#select-record").addEventListener("change", async function() {
    const recordId = this.value;
    if (!recordId) {
      currentRecord = null;
      displayOriginalData(null);
      container.querySelector("#break-records").innerHTML = 'なし';
      return;
    }

    const records = await window.aivicApi.list(1);
    if (records) {
      currentRecord = records.find(r => r.作業記録ID === recordId);
      if (currentRecord) {
        displayOriginalData(currentRecord);
        displayBreakRecords(recordId);

        // フォームに現在の値を設定
        const workDate = new Date(currentRecord.作業日);
        container.querySelector("#input-work-date").value = workDate.toISOString().split('T')[0];

        if (currentRecord.作業開始時刻) {
          const startTime = new Date(currentRecord.作業開始時刻);
          container.querySelector("#input-start-time").value = startTime.toTimeString().substring(0, 5);
        }

        if (currentRecord.作業終了時刻) {
          const endTime = new Date(currentRecord.作業終了時刻);
          container.querySelector("#input-end-time").value = endTime.toTimeString().substring(0, 5);
        }

        calculateTimes();
      }
    }
  });

  // 時間入力時の計算
  container.querySelector("#input-start-time").addEventListener("change", calculateTimes);
  container.querySelector("#input-end-time").addEventListener("change", calculateTimes);
  container.querySelector("#input-break-time").addEventListener("change", calculateTimes);

  // リセットボタン
  container.querySelector("#btn-reset").addEventListener("click", function() {
    container.querySelector("#select-record").value = "";
    container.querySelector("#input-work-date").value = "";
    container.querySelector("#input-start-time").value = "";
    container.querySelector("#input-end-time").value = "";
    container.querySelector("#select-work-item").value = "";
    container.querySelector("#input-break-time").value = "";
    container.querySelector("#select-break-reason").value = "";
    container.querySelector("#input-correction-reason").value = "";
    container.querySelector("#warning-area").classList.add("hidden");
    currentRecord = null;
    displayOriginalData(null);
    container.querySelector("#break-records").innerHTML = 'なし';
    calculateTimes();
  });

  // 修正保存ボタン
  container.querySelector("#btn-save").addEventListener("click", async function() {
    if (!currentRecord) {
      alert("修正対象の記録を選択してください");
      return;
    }

    const correctionReason = container.querySelector("#input-correction-reason").value.trim();
    if (!correctionReason) {
      alert("修正理由を入力してください");
      return;
    }

    const workDate = container.querySelector("#input-work-date").value;
    const startTime = container.querySelector("#input-start-time").value;
    const endTime = container.querySelector("#input-end-time").value;
    const workItemId = container.querySelector("#select-work-item").value;

    if (!workDate || !startTime) {
      alert("作業日付と開始時刻は必須です");
      return;
    }

    // 作業時間を計算
    let workTime = 0;
    if (startTime && endTime) {
      const start = new Date(`${workDate}T${startTime}`);
      const end = new Date(`${workDate}T${endTime}`);
      workTime = Math.max(0, (end - start) / (1000 * 60));
    }

    const updateData = {
      作業日: new Date(workDate).toISOString(),
      作業開始時刻: new Date(`${workDate}T${startTime}`).toISOString(),
      作業終了時刻: endTime ? new Date(`${workDate}T${endTime}`).toISOString() : null,
      作業時間: Math.round(workTime),
      更新日時: new Date().toISOString()
    };

    const updated = await window.aivicApi.update(1, currentRecord.作業記録ID, updateData);
    if (updated) {
      // 中断記録の処理
      const breakTime = container.querySelector("#input-break-time").value;
      const breakReason = container.querySelector("#select-break-reason").value;

      if (breakTime && breakReason) {
        const breakData = {
          作業記録ID: currentRecord.作業記録ID,
          中断開始日時: new Date(`${workDate}T${breakTime}`).toISOString(),
          中断理由区分: breakReason,
          対応状況: "記録済み",
          記録者ID: currentRecord.作業員ID,
          作成日時: new Date().toISOString(),
          更新日時: new Date().toISOString()
        };
        await window.aivicApi.save(2, breakData);
      }

      alert("修正が完了しました");
      container.querySelector("#btn-reset").click();
    }
  });

  // 戻るボタン
  container.querySelector("#btn-back").addEventListener("click", function() {
    window.showScreen("scr-1778907133295"); // 工数記録画面
  });

  // 履歴一覧ボタン
  container.querySelector("#btn-history").addEventListener("click", function() {
    window.showScreen("scr-1778907145716"); // 作業履歴一覧画面
  });

  // 初期化
  loadWorkItems();
  loadWorkRecords();
}

function(container, apiUrl, tables) {
  let selectedUrgency = '';
  let uploadedFiles = [];

  // 現在の日時を設定
  const now = new Date();
  now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
  container.querySelector('#occurrence-datetime').value = now.toISOString().slice(0, 16);

  // 報告者名を設定（ログインユーザー情報から取得）
  const currentUser = window.currentUser || { name: '作業員' };
  container.querySelector('#reporter-name').value = currentUser.name;

  // 作業項目マスタの読み込み
  async function loadWorkItems() {
    const workItems = await window.aivicApi.list(3); // 作業項目マスタ
    const select = container.querySelector('#work-item');
    if (workItems) {
      workItems
        .filter(item => item.有効フラグ)
        .sort((a, b) => (a.表示順序 || 0) - (b.表示順序 || 0))
        .forEach(item => {
          const option = document.createElement('option');
          option.value = item.作業項目ID;
          option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
          select.appendChild(option);
        });
    }
  }
  loadWorkItems();

  // 緊急度ボタンの処理
  container.addEventListener('click', (e) => {
    const urgencyBtn = e.target.closest('.urgency-btn');
    if (urgencyBtn) {
      // 全ボタンのスタイルをリセット
      container.querySelectorAll('.urgency-btn').forEach(btn => {
        btn.style.background = 'var(--bg-card)';
        btn.style.color = 'var(--text)';
        btn.style.borderColor = 'var(--border)';
      });

      // 選択されたボタンをハイライト
      selectedUrgency = urgencyBtn.dataset.level;
      container.querySelector('#urgency-level').value = selectedUrgency;

      if (selectedUrgency === '高') {
        urgencyBtn.style.background = '#d73027';
        urgencyBtn.style.color = '#fff';
        urgencyBtn.style.borderColor = '#d73027';
      } else if (selectedUrgency === '中') {
        urgencyBtn.style.background = '#fc8d59';
        urgencyBtn.style.color = '#fff';
        urgencyBtn.style.borderColor = '#fc8d59';
      } else {
        urgencyBtn.style.background = 'var(--primary)';
        urgencyBtn.style.color = '#fff';
        urgencyBtn.style.borderColor = 'var(--primary)';
      }
    }
  });

  // 写真選択ボタンの処理
  container.querySelector('#photo-btn').addEventListener('click', () => {
    container.querySelector('#photo-upload').click();
  });

  // 写真アップロード処理
  container.querySelector('#photo-upload').addEventListener('change', (e) => {
    const files = Array.from(e.target.files);
    files.forEach(file => {
      if (file.type.startsWith('image/')) {
        uploadedFiles.push(file);

        const reader = new FileReader();
        reader.onload = (e) => {
          const preview = document.createElement('div');
          preview.style.cssText = 'position: relative; border: 1px solid var(--border); border-radius: 6px; overflow: hidden;';
          preview.innerHTML = `
            <img src="${e.target.result}" style="width: 100%; height: 60px; object-fit: cover;">
            <button type="button" class="remove-photo" data-filename="${file.name}" style="position: absolute; top: 2px; right: 2px; width: 16px; height: 16px; border: none; background: rgba(0,0,0,0.7); color: #fff; border-radius: 50%; font-size: 10px; cursor: pointer; display: flex; align-items: center; justify-content: center;">×</button>
          `;
          container.querySelector('#photo-preview').appendChild(preview);
        };
        reader.readAsDataURL(file);
      }
    });
  });

  // 写真削除処理
  container.addEventListener('click', (e) => {
    const removeBtn = e.target.closest('.remove-photo');
    if (removeBtn) {
      const filename = removeBtn.dataset.filename;
      uploadedFiles = uploadedFiles.filter(f => f.name !== filename);
      removeBtn.closest('div').remove();
    }
  });

  // フォーカス時のスタイル適用
  container.querySelectorAll('input, select, textarea').forEach(element => {
    element.addEventListener('focus', () => {
      element.style.outline = 'none';
      element.style.borderColor = 'var(--primary)';
      element.style.boxShadow = '0 0 0 2px rgba(59, 130, 246, 0.15)';
    });

    element.addEventListener('blur', () => {
      element.style.borderColor = 'var(--border)';
      element.style.boxShadow = 'none';
    });
  });

  // 下書き保存
  container.querySelector('#btn-draft').addEventListener('click', async () => {
    const formData = collectFormData();
    formData.報告状態 = '下書き';

    const saved = await window.aivicApi.save(4, formData); // 異常値検出ログテーブルを緊急報告用に流用
    if (saved) {
      alert('下書きを保存しました');
    }
  });

  // 即座に報告
  container.querySelector('#btn-submit').addEventListener('click', async () => {
    if (!validateForm()) return;

    const formData = collectFormData();
    formData.報告状態 = '報告済み';
    formData.重要度 = selectedUrgency;
    formData.確認状況 = '未確認';
    formData.通知送信フラグ = true;

    const saved = await window.aivicApi.save(4, formData);
    if (saved) {
      // 完了モーダルを表示
      container.querySelector('#completion-modal').classList.remove('hidden');
    }
  });

  // 報告完了ボタン
  container.querySelector('#btn-complete').addEventListener('click', () => {
    window.showScreen("scr-1778907133295"); // 工数記録画面
  });

  // フォームデータ収集
  function collectFormData() {
    const workItemSelect = container.querySelector('#work-item');
    const selectedWorkItem = workItemSelect.options[workItemSelect.selectedIndex];

    return {
      検出対象テーブル: '緊急報告',
      検出対象レコードID: crypto.randomUUID(),
      ユーザーID: currentUser.id || crypto.randomUUID(),
      異常値種別: container.querySelector('#report-type').value,
      検出項目: '緊急事態内容',
      検出値: container.querySelector('#emergency-content').value,
      閾値: selectedUrgency,
      発生日時: container.querySelector('#occurrence-datetime').value,
      発生場所: container.querySelector('#location').value,
      作業項目: selectedWorkItem ? selectedWorkItem.textContent : '',
      連絡先電話番号: container.querySelector('#contact-phone').value,
      報告者名: container.querySelector('#reporter-name').value,
      添付ファイル数: uploadedFiles.length,
      検出日時: new Date().toISOString(),
      対応メモ: `緊急度: ${selectedUrgency}, 種別: ${container.querySelector('#report-type').value}`
    };
  }

  // フォームバリデーション
  function validateForm() {
    if (!selectedUrgency) {
      alert('緊急度を選択してください');
      return false;
    }

    const requiredFields = [
      { id: 'report-type', name: '報告種別' },
      { id: 'occurrence-datetime', name: '発生日時' },
      { id: 'location', name: '発生場所' },
      { id: 'emergency-content', name: '緊急事態内容' },
      { id: 'contact-phone', name: '連絡先電話番号' }
    ];

    for (const field of requiredFields) {
      const element = container.querySelector(`#${field.id}`);
      if (!element.value.trim()) {
        alert(`${field.name}を入力してください`);
        element.focus();
        return false;
      }
    }

    return true;
  }

  // モーダル外クリックで閉じる
  container.querySelector('#completion-modal').addEventListener('click', (e) => {
    if (e.target.id === 'completion-modal') {
      container.querySelector('#completion-modal').classList.add('hidden');
    }
  });
}

function(container, apiUrl, tables) {
  let currentRecordId = null;
  let originalData = null;

  // DOM要素の取得
  const selectWorkRecord = container.querySelector("#select-work-record");
  const inputWorkDate = container.querySelector("#input-work-date");
  const inputStartTime = container.querySelector("#input-start-time");
  const inputEndTime = container.querySelector("#input-end-time");
  const inputTotalTime = container.querySelector("#input-total-time");
  const inputBreakTime = container.querySelector("#input-break-time");
  const inputNetTime = container.querySelector("#input-net-time");
  const selectWorkItem = container.querySelector("#select-work-item");
  const inputCorrectionReason = container.querySelector("#input-correction-reason");
  const textareaWorkDetail = container.querySelector("#textarea-work-detail");
  const warningArea = container.querySelector("#warning-area");
  const warningMessage = container.querySelector("#warning-message");
  const btnSave = container.querySelector("#btn-save");
  const btnCancel = container.querySelector("#btn-cancel");
  const btnShowOriginal = container.querySelector("#btn-show-original");
  const originalDataModal = container.querySelector("#original-data-modal");
  const btnCloseModal = container.querySelector("#btn-close-modal");
  const originalDataContent = container.querySelector("#original-data-content");

  // 作業記録一覧の読み込み
  async function loadWorkRecords() {
    const records = await window.aivicApi.list(1); // 作業記録テーブル
    if (records) {
      selectWorkRecord.innerHTML = '<option value="">選択してください</option>';
      records.forEach(record => {
        const option = document.createElement('option');
        option.value = record.id;
        option.textContent = `${record.作業日 || ''} - ${record.プロジェクト名 || ''} (${record.作業種別 || ''})`;
        selectWorkRecord.appendChild(option);
      });
    }
  }

  // 作業項目マスタの読み込み
  async function loadWorkItems() {
    const items = await window.aivicApi.list(3); // 作業項目マスタテーブル
    if (items) {
      selectWorkItem.innerHTML = '<option value="">選択してください</option>';
      items.filter(item => item.有効フラグ).forEach(item => {
        const option = document.createElement('option');
        option.value = item.id;
        option.textContent = `${item.作業項目コード || ''} - ${item.作業項目名 || ''}`;
        selectWorkItem.appendChild(option);
      });
    }
  }

  // 時間計算
  function calculateTime() {
    const startTime = inputStartTime.value;
    const endTime = inputEndTime.value;
    const breakTime = parseInt(inputBreakTime.value) || 0;

    if (startTime && endTime) {
      const start = new Date(`2000-01-01 ${startTime}`);
      const end = new Date(`2000-01-01 ${endTime}`);

      if (end > start) {
        const totalMinutes = (end - start) / (1000 * 60);
        const hours = Math.floor(totalMinutes / 60);
        const minutes = totalMinutes % 60;
        inputTotalTime.value = `${hours}時間${minutes}分`;

        const netMinutes = totalMinutes - breakTime;
        if (netMinutes >= 0) {
          const netHours = Math.floor(netMinutes / 60);
          const netMins = netMinutes % 60;
          inputNetTime.value = `${netHours}時間${netMins}分`;

          // 異常値チェック
          checkAbnormalValues(totalMinutes, breakTime);
        } else {
          inputNetTime.value = '';
          showWarning('中断時間が作業時間を超えています');
        }
      } else {
        inputTotalTime.value = '';
        inputNetTime.value = '';
      }
    } else {
      inputTotalTime.value = '';
      inputNetTime.value = '';
    }
  }

  // 異常値チェック
  function checkAbnormalValues(totalMinutes, breakTime) {
    const warnings = [];

    if (totalMinutes > 12 * 60) { // 12時間超
      warnings.push('作業時間が12時間を超えています');
    }

    if (breakTime > totalMinutes * 0.5) { // 中断時間が作業時間の50%超
      warnings.push('中断時間が作業時間の50%を超えています');
    }

    if (totalMinutes < 30) { // 30分未満
      warnings.push('作業時間が30分未満です');
    }

    if (warnings.length > 0) {
      showWarning(warnings.join('、'));
    } else {
      hideWarning();
    }
  }

  // 警告表示
  function showWarning(message) {
    warningMessage.textContent = message;
    warningArea.classList.remove('hidden');
  }

  // 警告非表示
  function hideWarning() {
    warningArea.classList.add('hidden');
  }

  // 作業記録選択時の処理
  selectWorkRecord.addEventListener('change', async function() {
    const recordId = this.value;
    if (recordId) {
      const records = await window.aivicApi.list(1);
      const record = records?.find(r => r.id === recordId);
      if (record) {
        currentRecordId = recordId;
        originalData = record;

        // フォームに既存データを設定
        inputWorkDate.value = record.作業日 ? new Date(record.作業日).toLocaleDateString('ja-JP') : '';

        if (record.作業開始時刻) {
          const startTime = new Date(record.作業開始時刻);
          inputStartTime.value = startTime.toTimeString().slice(0, 5);
        }

        if (record.作業終了時刻) {
          const endTime = new Date(record.作業終了時刻);
          inputEndTime.value = endTime.toTimeString().slice(0, 5);
        }

        textareaWorkDetail.value = record.作業内容 || '';

        // 中断時間の取得
        const breakRecords = await window.aivicApi.list(2); // 中断記録テーブル
        const totalBreakTime = breakRecords?.filter(br => br.作業記録ID === recordId)
          .reduce((sum, br) => sum + (br.中断時間 || 0), 0) || 0;
        inputBreakTime.value = totalBreakTime;

        calculateTime();
      }
    } else {
      currentRecordId = null;
      originalData = null;
      // フォームをクリア
      inputWorkDate.value = '';
      inputStartTime.value = '';
      inputEndTime.value = '';
      inputTotalTime.value = '';
      inputBreakTime.value = '';
      inputNetTime.value = '';
      textareaWorkDetail.value = '';
      inputCorrectionReason.value = '';
      hideWarning();
    }
  });

  // 時間入力時の計算
  inputStartTime.addEventListener('change', calculateTime);
  inputEndTime.addEventListener('change', calculateTime);
  inputBreakTime.addEventListener('input', calculateTime);

  // 元データ参照ボタン
  btnShowOriginal.addEventListener('click', function() {
    if (originalData) {
      const content = `
        <div style="display: grid; grid-template-columns: 120px 1fr; gap: 8px; margin-bottom: 8px;">
          <strong>作業日:</strong><span>${originalData.作業日 ? new Date(originalData.作業日).toLocaleDateString('ja-JP') : ''}</span>
          <strong>開始時刻:</strong><span>${originalData.作業開始時刻 ? new Date(originalData.作業開始時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : ''}</span>
          <strong>終了時刻:</strong><span>${originalData.作業終了時刻 ? new Date(originalData.作業終了時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : ''}</span>
          <strong>作業時間:</strong><span>${originalData.作業時間 ? Math.floor(originalData.作業時間/60) + '時間' + (originalData.作業時間%60) + '分' : ''}</span>
          <strong>プロジェクト:</strong><span>${originalData.プロジェクト名 || ''}</span>
          <strong>作業場所:</strong><span>${originalData.作業場所 || ''}</span>
          <strong>作業種別:</strong><span>${originalData.作業種別 || ''}</span>
          <strong>作業内容:</strong><span>${originalData.作業内容 || ''}</span>
          <strong>進捗状況:</strong><span>${originalData.進捗状況 || ''}</span>
          <strong>承認状態:</strong><span>${originalData.承認状態 || ''}</span>
        </div>
      `;
      originalDataContent.innerHTML = content;
      originalDataModal.classList.remove('hidden');
    }
  });

  // モーダル閉じる
  btnCloseModal.addEventListener('click', function() {
    originalDataModal.classList.add('hidden');
  });

  // モーダル背景クリックで閉じる
  originalDataModal.addEventListener('click', function(e) {
    if (e.target === originalDataModal) {
      originalDataModal.classList.add('hidden');
    }
  });

  // キャンセルボタン
  btnCancel.addEventListener('click', function() {
    if (confirm('修正内容を破棄しますか？')) {
      window.showScreen("scr-1778907367889");
    }
  });

  // 修正完了ボタン
  btnSave.addEventListener('click', async function() {
    if (!currentRecordId) {
      alert('修正対象の作業記録を選択してください');
      return;
    }

    if (!inputCorrectionReason.value.trim()) {
      alert('修正理由を入力してください');
      return;
    }

    if (!inputStartTime.value || !inputEndTime.value) {
      alert('作業開始時刻と終了時刻を入力してください');
      return;
    }

    const startDateTime = new Date(`${inputWorkDate.value} ${inputStartTime.value}`);
    const endDateTime = new Date(`${inputWorkDate.value} ${inputEndTime.value}`);
    const workTimeMinutes = (endDateTime - startDateTime) / (1000 * 60);

    const updateData = {
      作業開始時刻: startDateTime.toISOString(),
      作業終了時刻: endDateTime.toISOString(),
      作業時間: workTimeMinutes,
      作業内容: textareaWorkDetail.value.trim(),
      更新日時: new Date().toISOString()
    };

    const result = await window.aivicApi.update(1, currentRecordId, updateData);
    if (result) {
      // 異常値ログの記録
      if (!warningArea.classList.contains('hidden')) {
        const logData = {
          検出対象テーブル: '作業記録',
          検出対象レコードID: currentRecordId,
          ユーザーID: 'current-user', // 実際の実装では現在のユーザーIDを使用
          異常値種別: '修正データ異常値',
          検出項目: '作業時間',
          検出値: `${Math.floor(workTimeMinutes/60)}時間${workTimeMinutes%60}分`,
          閾値: '標準範囲外',
          重要度: '中',
          確認状況: '未確認',
          通知送信フラグ: false,
          検出日時: new Date().toISOString(),
          作成日時: new Date().toISOString(),
          更新日時: new Date().toISOString()
        };
        await window.aivicApi.save(4, logData); // 異常値検出ログテーブル
      }

      alert('工数データを修正しました');
      window.showScreen("scr-1778907367889");
    }
  });

  // 初期データ読み込み
  loadWorkRecords();
  loadWorkItems();
}

function(container, apiUrl, tables) {
  // データ取得
  let workRecords = [];
  let users = [];
  let workItems = [];
  let interruptions = [];
  let anomalies = [];

  // 初期データ設定
  async function loadInitialData() {
    try {
      workRecords = await window.aivicApi.list(1) || tables[1]?.records || [];
      users = await window.aivicApi.list(0) || tables[0]?.records || [];
      workItems = await window.aivicApi.list(3) || tables[3]?.records || [];
      interruptions = await window.aivicApi.list(2) || tables[2]?.records || [];
      anomalies = await window.aivicApi.list(4) || tables[4]?.records || [];

      populateSelects();
    } catch (error) {
      console.error('データ読み込みエラー:', error);
    }
  }

  // セレクトボックスにオプション設定
  function populateSelects() {
    const workersSelect = container.querySelector('#select-workers');
    const locationsSelect = container.querySelector('#select-locations');
    const workItemsSelect = container.querySelector('#select-work-items');

    // 作業員オプション
    workersSelect.innerHTML = users.map(user => 
      `<option value="${user.id}">${user.氏名 || user.ユーザー名 || ''}</option>`
    ).join('');

    // 作業場所オプション（重複除去）
    const locations = [...new Set(workRecords.map(r => r.作業場所).filter(Boolean))];
    locationsSelect.innerHTML = locations.map(loc => 
      `<option value="${loc}">${loc}</option>`
    ).join('');

    // 作業項目オプション
    workItemsSelect.innerHTML = workItems.map(item => 
      `<option value="${item.id}">${item.作業項目名 || ''}</option>`
    ).join('');
  }

  // 条件プレビュー更新
  function updateConditionPreview() {
    const startDate = container.querySelector('#input-start-date').value;
    const endDate = container.querySelector('#input-end-date').value;
    const selectedWorkers = Array.from(container.querySelector('#select-workers').selectedOptions).map(o => o.text);
    const selectedLocations = Array.from(container.querySelector('#select-locations').selectedOptions).map(o => o.value);
    const selectedWorkItems = Array.from(container.querySelector('#select-work-items').selectedOptions).map(o => o.text);
    const includeAnomaly = container.querySelector('#check-include-anomaly').checked;
    const includeInterruption = container.querySelector('#check-include-interruption').checked;
    const format = container.querySelector('#select-format').value;

    let preview = [];
    if (startDate || endDate) {
      preview.push(`期間: ${startDate || '指定なし'} ～ ${endDate || '指定なし'}`);
    }
    if (selectedWorkers.length > 0) {
      preview.push(`作業員: ${selectedWorkers.join(', ')}`);
    }
    if (selectedLocations.length > 0) {
      preview.push(`作業場所: ${selectedLocations.join(', ')}`);
    }
    if (selectedWorkItems.length > 0) {
      preview.push(`作業項目: ${selectedWorkItems.join(', ')}`);
    }
    preview.push(`異常値データ: ${includeAnomaly ? '含む' : '除外'}`);
    preview.push(`中断記録: ${includeInterruption ? '含む' : '除外'}`);
    preview.push(`出力形式: ${format.toUpperCase()}`);

    container.querySelector('#condition-preview').textContent = preview.join(' | ');
  }

  // データフィルタリング
  function filterData() {
    const startDate = container.querySelector('#input-start-date').value;
    const endDate = container.querySelector('#input-end-date').value;
    const selectedWorkerIds = Array.from(container.querySelector('#select-workers').selectedOptions).map(o => o.value);
    const selectedLocations = Array.from(container.querySelector('#select-locations').selectedOptions).map(o => o.value);
    const selectedWorkItemIds = Array.from(container.querySelector('#select-work-items').selectedOptions).map(o => o.value);
    const includeAnomaly = container.querySelector('#check-include-anomaly').checked;

    let filtered = workRecords.filter(record => {
      // 期間フィルタ
      if (startDate && record.作業日 && new Date(record.作業日) < new Date(startDate)) return false;
      if (endDate && record.作業日 && new Date(record.作業日) > new Date(endDate)) return false;

      // 作業員フィルタ
      if (selectedWorkerIds.length > 0 && !selectedWorkerIds.includes(record.作業員ID)) return false;

      // 作業場所フィルタ
      if (selectedLocations.length > 0 && !selectedLocations.includes(record.作業場所)) return false;

      // 作業項目フィルタ（作業種別で判定）
      if (selectedWorkItemIds.length > 0) {
        const matchingItem = workItems.find(item => 
          selectedWorkItemIds.includes(item.id) && 
          (item.作業項目名 === record.作業種別 || item.カテゴリ === record.作業種別)
        );
        if (!matchingItem) return false;
      }

      // 異常値データフィルタ
      if (!includeAnomaly) {
        const hasAnomaly = anomalies.some(anomaly => 
          anomaly.検出対象レコードID === record.id && anomaly.検出対象テーブル === '作業記録'
        );
        if (hasAnomaly) return false;
      }

      return true;
    });

    return filtered;
  }

  // プレビューテーブル描画
  function renderPreview(data) {
    const tbody = container.querySelector('#preview-tbody');
    const previewData = data.slice(0, 50);

    if (previewData.length === 0) {
      tbody.innerHTML = '<tr><td colspan="7" style="text-align: center; color: var(--text-muted); padding: 20px;">条件に該当するデータがありません</td></tr>';
      return;
    }

    tbody.innerHTML = previewData.map(record => {
      const worker = users.find(u => u.id === record.作業員ID);
      const workTime = record.作業時間 ? `${Math.floor(record.作業時間 / 60)}h${record.作業時間 % 60}m` : '-';

      return `
        <tr>
          <td>${record.作業日 ? new Date(record.作業日).toLocaleDateString('ja-JP') : '-'}</td>
          <td>${worker?.氏名 || worker?.ユーザー名 || '-'}</td>
          <td>${record.作業場所 || '-'}</td>
          <td>${record.作業種別 || '-'}</td>
          <td>${workTime}</td>
          <td>${record.進捗状況 || '-'}</td>
          <td>${record.承認状態 || '-'}</td>
        </tr>
      `;
    }).join('');
  }

  // CSV生成
  function generateCSV(data) {
    const includeInterruption = container.querySelector('#check-include-interruption').checked;

    let headers = ['作業日', '作業員名', '作業場所', '作業種別', '作業内容', '作業開始時刻', '作業終了時刻', '作業時間(分)', '進捗状況', '承認状態', '承認者', '備考'];

    if (includeInterruption) {
      headers.push('中断回数', '総中断時間(分)', '主な中断理由');
    }

    let csvContent = '\uFEFF' + headers.join(',') + '\n';

    data.forEach(record => {
      const worker = users.find(u => u.id === record.作業員ID);
      const approver = users.find(u => u.id === record.承認者ID);

      let row = [
        record.作業日 ? new Date(record.作業日).toLocaleDateString('ja-JP') : '',
        worker?.氏名 || worker?.ユーザー名 || '',
        record.作業場所 || '',
        record.作業種別 || '',
        `"${(record.作業内容 || '').replace(/"/g, '""')}"`,
        record.作業開始時刻 ? new Date(record.作業開始時刻).toLocaleString('ja-JP') : '',
        record.作業終了時刻 ? new Date(record.作業終了時刻).toLocaleString('ja-JP') : '',
        record.作業時間 || '',
        record.進捗状況 || '',
        record.承認状態 || '',
        approver?.氏名 || approver?.ユーザー名 || '',
        `"${(record.備考 || '').replace(/"/g, '""')}"`
      ];

      if (includeInterruption) {
        const recordInterruptions = interruptions.filter(i => i.作業記録ID === record.id);
        const interruptionCount = recordInterruptions.length;
        const totalInterruptionTime = recordInterruptions.reduce((sum, i) => sum + (i.中断時間 || 0), 0);
        const mainReasons = [...new Set(recordInterruptions.map(i => i.中断理由区分).filter(Boolean))].join(';');

        row.push(interruptionCount, totalInterruptionTime, `"${mainReasons}"`);
      }

      csvContent += row.join(',') + '\n';
    });

    return csvContent;
  }

  // イベントリスナー設定
  container.querySelector('#btn-back').addEventListener('click', () => {
    window.showScreen("scr-1778907145716");
  });

  container.querySelector('#btn-preview').addEventListener('click', () => {
    const filteredData = filterData();
    renderPreview(filteredData);
    updateConditionPreview();
    container.querySelector('#data-count').textContent = `対象件数: ${filteredData.length}件`;
  });

  container.querySelector('#btn-extract').addEventListener('click', () => {
    const filteredData = filterData();
    if (filteredData.length === 0) {
      alert('抽出対象のデータがありません。条件を確認してください。');
      return;
    }

    const format = container.querySelector('#select-format').value;
    const csvContent = generateCSV(filteredData);

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', `工数記録データ_${new Date().toISOString().slice(0, 10)}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  });

  container.querySelector('#btn-clear-condition').addEventListener('click', () => {
    container.querySelector('#input-start-date').value = '';
    container.querySelector('#input-end-date').value = '';
    container.querySelector('#select-workers').selectedIndex = -1;
    container.querySelector('#select-locations').selectedIndex = -1;
    container.querySelector('#select-work-items').selectedIndex = -1;
    container.querySelector('#check-include-anomaly').checked = false;
    container.querySelector('#check-include-interruption').checked = false;
    container.querySelector('#select-format').value = 'csv';
    container.querySelector('#condition-preview').textContent = '条件を設定してプレビューボタンを押してください';
    container.querySelector('#data-count').textContent = '対象件数: -';
    container.querySelector('#preview-tbody').innerHTML = '<tr><td colspan="7" style="text-align: center; color: var(--text-muted); padding: 20px;">プレビューを実行してください</td></tr>';
  });

  container.querySelector('#btn-save-condition').addEventListener('click', () => {
    const conditions = {
      startDate: container.querySelector('#input-start-date').value,
      endDate: container.querySelector('#input-end-date').value,
      workers: Array.from(container.querySelector('#select-workers').selectedOptions).map(o => o.value),
      locations: Array.from(container.querySelector('#select-locations').selectedOptions).map(o => o.value),
      workItems: Array.from(container.querySelector('#select-work-items').selectedOptions).map(o => o.value),
      includeAnomaly: container.querySelector('#check-include-anomaly').checked,
      includeInterruption: container.querySelector('#check-include-interruption').checked,
      format: container.querySelector('#select-format').value
    };

    localStorage.setItem('extractionConditions', JSON.stringify(conditions));
    alert('抽出条件を保存しました。');
  });

  // 条件変更時のプレビュー更新
  ['#input-start-date', '#input-end-date', '#select-workers', '#select-locations', '#select-work-items', '#check-include-anomaly', '#check-include-interruption', '#select-format'].forEach(selector => {
    const element = container.querySelector(selector);
    if (element) {
      element.addEventListener('change', updateConditionPreview);
    }
  });

  // 保存された条件の復元
  function loadSavedConditions() {
    const saved = localStorage.getItem('extractionConditions');
    if (saved) {
      try {
        const conditions = JSON.parse(saved);
        container.querySelector('#input-start-date').value = conditions.startDate || '';
        container.querySelector('#input-end-date').value = conditions.endDate || '';
        container.querySelector('#check-include-anomaly').checked = conditions.includeAnomaly || false;
        container.querySelector('#check-include-interruption').checked = conditions.includeInterruption || false;
        container.querySelector('#select-format').value = conditions.format || 'csv';

        // 複数選択の復元
        if (conditions.workers) {
          Array.from(container.querySelector('#select-workers').options).forEach(option => {
            option.selected = conditions.workers.includes(option.value);
          });
        }
        if (conditions.locations) {
          Array.from(container.querySelector('#select-locations').options).forEach(option => {
            option.selected = conditions.locations.includes(option.value);
          });
        }
        if (conditions.workItems) {
          Array.from(container.querySelector('#select-work-items').options).forEach(option => {
            option.selected = conditions.workItems.includes(option.value);
          });
        }
      } catch (error) {
        console.error('保存条件の復元エラー:', error);
      }
    }
  }

  // 初期化
  loadInitialData().then(() => {
    loadSavedConditions();
    updateConditionPreview();
  });
}

function(container, apiUrl, tables) {
  let currentRecordId = null;

  // 時刻フォーマット関数
  function formatTime(timestamp) {
    if (!timestamp) return '-';
    const date = new Date(timestamp);
    return date.toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });
  }

  // 日付フォーマット関数
  function formatDate(timestamp) {
    if (!timestamp) return '-';
    const date = new Date(timestamp);
    return date.toLocaleDateString('ja-JP');
  }

  // 分を時間表示に変換
  function formatMinutes(minutes) {
    if (!minutes) return '-';
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return hours > 0 ? `${hours}時間${mins}分` : `${mins}分`;
  }

  // 作業項目テーブル再描画
  function renderWorkItems(workRecords) {
    const tbody = container.querySelector('#work-items-tbody');
    tbody.innerHTML = workRecords.map(record => `
      <tr data-id="${record.id}">
        <td>${record.プロジェクト名 || '-'}</td>
        <td>${record.作業場所 || '-'}</td>
        <td>${record.作業種別 || '-'}</td>
        <td style="max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="${record.作業内容 || ''}">${record.作業内容 || '-'}</td>
        <td>
          <span style="font-size: 12px; padding: 2px 6px; border-radius: 3px; background: ${record.進捗状況 === '完了' ? '#d4edda' : record.進捗状況 === '作業中' ? '#fff3cd' : '#f8d7da'}; color: ${record.進捗状況 === '完了' ? '#155724' : record.進捗状況 === '作業中' ? '#856404' : '#721c24'};">
            ${record.進捗状況 || '-'}
          </span>
        </td>
        <td style="text-align: right; font-weight: 500;">${record.作業時間 || 0}</td>
      </tr>
    `).join('');
  }

  // 中断記録テーブル再描画
  function renderBreakRecords(breakRecords) {
    const tbody = container.querySelector('#break-records-tbody');
    if (!breakRecords || breakRecords.length === 0) {
      tbody.innerHTML = '<tr><td colspan="6" style="text-align: center; color: var(--text-muted); padding: 16px;">中断記録はありません</td></tr>';
      return;
    }

    tbody.innerHTML = breakRecords.map(record => `
      <tr data-id="${record.id}">
        <td>${formatTime(record.中断開始日時)}</td>
        <td>${formatTime(record.中断終了日時)}</td>
        <td style="text-align: right;">${record.中断時間 || 0}</td>
        <td>${record.中断理由区分 || '-'}</td>
        <td style="max-width: 150px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="${record.中断理由詳細 || ''}">${record.中断理由詳細 || '-'}</td>
        <td>
          <span style="font-size: 12px; padding: 2px 6px; border-radius: 3px; background: ${record.影響度 === '軽微' ? '#d4edda' : record.影響度 === '中程度' ? '#fff3cd' : '#f8d7da'}; color: ${record.影響度 === '軽微' ? '#155724' : record.影響度 === '中程度' ? '#856404' : '#721c24'};">
            ${record.影響度 || '-'}
          </span>
        </td>
      </tr>
    `).join('');
  }

  // メイン画面更新
  async function updateDisplay(recordId) {
    try {
      // 作業記録取得
      const workRecords = await window.aivicApi.list(1);
      const currentRecord = workRecords.find(r => r.id === recordId);

      if (!currentRecord) {
        alert('作業記録が見つかりません');
        return;
      }

      currentRecordId = recordId;

      // 作業員情報取得
      const users = await window.aivicApi.list(0);
      const worker = users.find(u => u.id === currentRecord.作業員ID);

      // 中断記録取得
      const breakRecords = await window.aivicApi.list(2);
      const relatedBreaks = breakRecords.filter(b => b.作業記録ID === recordId);

      // 異常値検出ログ取得
      const anomalyLogs = await window.aivicApi.list(4);
      const hasAnomaly = anomalyLogs.some(log => 
        log.検出対象レコードID === recordId && log.確認状況 === '未確認'
      );

      // 基本情報表示
      container.querySelector('#worker-name').textContent = worker ? worker.氏名 : '-';
      container.querySelector('#work-date').textContent = formatDate(currentRecord.作業日);

      // 承認状態
      const statusEl = container.querySelector('#approval-status');
      statusEl.textContent = currentRecord.承認状態 || '未承認';
      statusEl.style.background = currentRecord.承認状態 === '承認済み' ? '#d4edda' : 
                                  currentRecord.承認状態 === '差し戻し' ? '#f8d7da' : '#f0f0f0';
      statusEl.style.color = currentRecord.承認状態 === '承認済み' ? '#155724' : 
                            currentRecord.承認状態 === '差し戻し' ? '#721c24' : '#666';

      // 異常値警告
      const warningEl = container.querySelector('#anomaly-warning');
      if (hasAnomaly) {
        warningEl.classList.remove('hidden');
      } else {
        warningEl.classList.add('hidden');
      }

      // 時間情報
      container.querySelector('#start-time').textContent = formatTime(currentRecord.作業開始時刻);
      container.querySelector('#end-time').textContent = formatTime(currentRecord.作業終了時刻);
      container.querySelector('#work-hours').textContent = formatMinutes(currentRecord.作業時間);

      // 中断時間合計
      const totalBreakTime = relatedBreaks.reduce((sum, b) => sum + (b.中断時間 || 0), 0);
      container.querySelector('#break-hours').textContent = formatMinutes(totalBreakTime);

      // 合計工数
      const totalHours = (currentRecord.作業時間 || 0) + totalBreakTime;
      container.querySelector('#total-hours').textContent = formatMinutes(totalHours);

      // 作業内容・備考
      container.querySelector('#work-detail').textContent = currentRecord.作業内容 || '-';
      container.querySelector('#work-memo').textContent = currentRecord.備考 || '-';

      // テーブル更新
      renderWorkItems([currentRecord]);
      renderBreakRecords(relatedBreaks);

    } catch (error) {
      console.error('データ取得エラー:', error);
    }
  }

  // 修正ボタン
  container.querySelector('#btn-modify').addEventListener('click', () => {
    if (currentRecordId) {
      window.showScreen("scr-1778907343735");
    } else {
      alert('修正対象の記録が選択されていません');
    }
  });

  // 承認ボタン
  container.querySelector('#btn-approve').addEventListener('click', async () => {
    if (!currentRecordId) {
      alert('承認対象の記録が選択されていません');
      return;
    }

    if (!confirm('この工数記録を承認しますか？')) return;

    try {
      const updated = await window.aivicApi.update(1, currentRecordId, {
        承認状態: '承認済み',
        承認日時: new Date().toISOString(),
        承認者ID: 'current-user-id' // 実際の実装では現在のユーザーIDを使用
      });

      if (updated) {
        alert('承認が完了しました');
        updateDisplay(currentRecordId);
      }
    } catch (error) {
      console.error('承認エラー:', error);
      alert('承認処理に失敗しました');
    }
  });

  // 初期表示（最初の作業記録を表示）
  if (tables[1] && tables[1].records && tables[1].records.length > 0) {
    updateDisplay(tables[1].records[0].id);
  }
}

function(container, apiUrl, tables) {
  let currentUserId = 'user-001'; // 仮のユーザーID
  let breakRecords = [];

  // 作業項目マスタの読み込み
  function loadWorkItems() {
    const workItemSelect = container.querySelector('#select-work-item');
    if (tables[3] && tables[3].records) {
      tables[3].records.forEach(item => {
        if (item.有効フラグ) {
          const option = document.createElement('option');
          option.value = item.作業項目ID;
          option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
          workItemSelect.appendChild(option);
        }
      });
    }
  }

  // 担当者名の表示
  function loadWorkerName() {
    const workerNameDisplay = container.querySelector('#display-worker-name');
    if (tables[0] && tables[0].records) {
      const currentUser = tables[0].records.find(user => user.ユーザーID === currentUserId);
      if (currentUser) {
        workerNameDisplay.textContent = currentUser.氏名;
      }
    }
  }

  // 工数計算
  function calculateWorkHours() {
    const startTime = container.querySelector('#input-start-time').value;
    const endTime = container.querySelector('#input-end-time').value;

    if (!startTime || !endTime) {
      container.querySelector('#display-work-hours').textContent = '0時間 0分';
      container.querySelector('#display-total-hours').textContent = '0時間 0分';
      return;
    }

    const start = new Date(`2000-01-01T${startTime}`);
    const end = new Date(`2000-01-01T${endTime}`);

    if (end <= start) {
      container.querySelector('#display-work-hours').textContent = '0時間 0分';
      container.querySelector('#display-total-hours').textContent = '0時間 0分';
      return;
    }

    const totalMinutes = (end - start) / (1000 * 60);
    const breakMinutes = breakRecords.reduce((sum, record) => {
      if (record.中断時間) {
        return sum + record.中断時間;
      }
      return sum;
    }, 0);

    const workMinutes = Math.max(0, totalMinutes - breakMinutes);
    const workHours = Math.floor(workMinutes / 60);
    const workMins = workMinutes % 60;

    const totalHours = Math.floor(totalMinutes / 60);
    const totalMins = totalMinutes % 60;

    container.querySelector('#display-work-hours').textContent = `${workHours}時間 ${workMins}分`;
    container.querySelector('#display-break-time').textContent = `${breakMinutes}分`;
    container.querySelector('#display-total-hours').textContent = `${totalHours}時間 ${totalMins}分`;
  }

  // 中断記録テーブルの再描画
  function renderBreakRecords() {
    const tbody = container.querySelector('#break-records-tbody');
    if (breakRecords.length === 0) {
      tbody.innerHTML = '<tr><td colspan="5" style="text-align: center; color: var(--text-muted); font-size: 12px;">中断記録はありません</td></tr>';
      return;
    }

    tbody.innerHTML = breakRecords.map((record, index) => `
      <tr data-index="${index}">
        <td>${record.中断開始日時 ? new Date(record.中断開始日時).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '-'}</td>
        <td>${record.中断終了日時 ? new Date(record.中断終了日時).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '-'}</td>
        <td>${record.中断理由区分 || '-'}</td>
        <td>${record.中断時間 ? record.中断時間 + '分' : '-'}</td>
        <td><button class="action-btn secondary delete-break-btn" data-index="${index}">削除</button></td>
      </tr>
    `).join('');
  }

  // 初期化
  loadWorkItems();
  loadWorkerName();

  // 現在日時の設定
  const now = new Date();
  container.querySelector('#input-work-date').value = now.toISOString().split('T')[0];
  container.querySelector('#input-start-time').value = now.toTimeString().slice(0, 5);

  // 時刻変更時の工数計算
  container.querySelector('#input-start-time').addEventListener('change', calculateWorkHours);
  container.querySelector('#input-end-time').addEventListener('change', calculateWorkHours);

  // 中断時間追加ボタン
  container.querySelector('#btn-add-break').addEventListener('click', () => {
    window.showScreen('scr-1778907238439');
  });

  // 中断記録削除
  container.addEventListener('click', (e) => {
    const deleteBtn = e.target.closest('.delete-break-btn');
    if (deleteBtn) {
      const index = parseInt(deleteBtn.dataset.index);
      if (confirm('この中断記録を削除しますか？')) {
        breakRecords.splice(index, 1);
        renderBreakRecords();
        calculateWorkHours();
      }
    }
  });

  // 一時保存ボタン
  container.querySelector('#btn-temp-save').addEventListener('click', async () => {
    const workData = {
      作業員ID: currentUserId,
      作業日: new Date(container.querySelector('#input-work-date').value),
      作業開始時刻: container.querySelector('#input-start-time').value ? 
        new Date(`${container.querySelector('#input-work-date').value}T${container.querySelector('#input-start-time').value}`) : null,
      作業終了時刻: container.querySelector('#input-end-time').value ? 
        new Date(`${container.querySelector('#input-work-date').value}T${container.querySelector('#input-end-time').value}`) : null,
      プロジェクト名: container.querySelector('#input-project-name').value,
      作業場所: container.querySelector('#input-work-location').value,
      作業種別: container.querySelector('#select-work-type').value,
      作業内容: container.querySelector('#textarea-work-detail').value,
      進捗状況: '作業中',
      承認状態: '未承認',
      作成日時: new Date(),
      更新日時: new Date(),
      作成者ID: currentUserId
    };

    const saved = await window.aivicApi.save(1, workData);
    if (saved) {
      alert('一時保存しました');
    }
  });

  // 記録確定ボタン
  container.querySelector('#btn-confirm').addEventListener('click', async () => {
    const workDate = container.querySelector('#input-work-date').value;
    const startTime = container.querySelector('#input-start-time').value;
    const endTime = container.querySelector('#input-end-time').value;
    const projectName = container.querySelector('#input-project-name').value;
    const workLocation = container.querySelector('#input-work-location').value;
    const workType = container.querySelector('#select-work-type').value;
    const workDetail = container.querySelector('#textarea-work-detail').value;

    if (!workDate || !startTime || !projectName || !workLocation || !workType || !workDetail) {
      alert('必須項目を入力してください');
      return;
    }

    const startDateTime = new Date(`${workDate}T${startTime}`);
    const endDateTime = endTime ? new Date(`${workDate}T${endTime}`) : null;
    const workMinutes = endDateTime ? (endDateTime - startDateTime) / (1000 * 60) : 0;

    const workData = {
      作業員ID: currentUserId,
      作業日: new Date(workDate),
      作業開始時刻: startDateTime,
      作業終了時刻: endDateTime,
      作業時間: workMinutes,
      プロジェクト名: projectName,
      作業場所: workLocation,
      作業種別: workType,
      作業内容: workDetail,
      進捗状況: endDateTime ? '完了' : '作業中',
      承認状態: '未承認',
      作成日時: new Date(),
      更新日時: new Date(),
      作成者ID: currentUserId
    };

    const saved = await window.aivicApi.save(1, workData);
    if (saved) {
      // 中断記録も保存
      for (const breakRecord of breakRecords) {
        breakRecord.作業記録ID = saved.作業記録ID;
        await window.aivicApi.save(2, breakRecord);
      }

      alert('工数記録を確定しました');
      window.showScreen('scr-1778907226171');
    }
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    if (confirm('入力内容を破棄して戻りますか？')) {
      window.showScreen('scr-1778907133295');
    }
  });

  // 履歴一覧ボタン
  container.querySelector('#btn-history').addEventListener('click', () => {
    window.showScreen('scr-1778907145716');
  });

  // 中断記録ボタン
  container.querySelector('#btn-break').addEventListener('click', () => {
    window.showScreen('scr-1778907238439');
  });

  // 初期描画
  renderBreakRecords();
  calculateWorkHours();
}
